INSERT INTO `cms_page_translations` VALUES (1,'About Us','about-us','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>Kawaii Blessings — About Us</title>\r\n<meta name=\"description\" content=\"Meet Kawaii Blessings, a UAE-based kawaii store bringing genuine, brand-new and adorable products to collectors and gift lovers.\">\r\n<style>\r\n:root {\r\n  --kb-bg:#fff9fb;\r\n  --kb-bg-2:#fff3f7;\r\n  --kb-card:#ffffff;\r\n  --kb-blush:#fff0f5;\r\n  --kb-pink:#f58fb0;\r\n  --kb-pink-2:#ed6e98;\r\n  --kb-pink-3:#ffd5e3;\r\n  --kb-cocoa:#493137;\r\n  --kb-text:#5b3a45;\r\n  --kb-muted:#8e6c78;\r\n  --kb-line:#f4cad8;\r\n  --kb-lav:#d9c8f3;\r\n  --kb-mint:#ddf2e6;\r\n  --kb-butter:#fff1b8;\r\n  --kb-shadow:0 14px 40px rgba(197,83,124,.09);\r\n  --kb-shadow-hover:0 22px 55px rgba(197,83,124,.16);\r\n}\r\n*{box-sizing:border-box}\r\nhtml{scroll-behavior:smooth}\r\nbody{\r\n  margin:0;\r\n  color:var(--kb-text);\r\n  font-family:\"Trebuchet MS\",\"Avenir Next\",Avenir,Arial,sans-serif;\r\n  background:\r\n    radial-gradient(circle at 10% 6%,rgba(245,143,176,.11),transparent 22%),\r\n    radial-gradient(circle at 88% 22%,rgba(217,200,243,.13),transparent 20%),\r\n    linear-gradient(180deg,#fffafb 0%,#fffefe 43%,#fff7fa 100%);\r\n  overflow-x:hidden;\r\n}\r\na{color:inherit;text-decoration:none}\r\nimg{max-width:100%;display:block}\r\nbutton,a{-webkit-tap-highlight-color:transparent}\r\n\r\n.kb-page{\r\n  width:min(1180px,calc(100% - 34px));\r\n  margin:0 auto;\r\n  padding:30px 0 36px;\r\n  position:relative;\r\n  isolation:isolate;\r\n}\r\n.kb-section{margin-top:18px}\r\n.kb-card{\r\n  background:rgba(255,255,255,.94);\r\n  border:1px solid var(--kb-line);\r\n  border-radius:24px;\r\n  box-shadow:0 1px 0 rgba(255,255,255,.9) inset,var(--kb-shadow);\r\n  overflow:hidden;\r\n  position:relative;\r\n}\r\n.kb-card::after{\r\n  content:\"\";\r\n  position:absolute;\r\n  inset:0;\r\n  pointer-events:none;\r\n  background:linear-gradient(120deg,transparent 25%,rgba(255,255,255,.36) 48%,transparent 68%);\r\n  transform:translateX(-130%);\r\n}\r\n.kb-card:hover::after{animation:cardSweep 1.2s ease}\r\n\r\n.kb-bg-particles{position:fixed;inset:0;pointer-events:none;z-index:-1;overflow:hidden}\r\n.kb-particle{\r\n  position:absolute;\r\n  opacity:.22;\r\n  animation:drift var(--dur) ease-in-out infinite alternate;\r\n  filter:drop-shadow(0 6px 8px rgba(237,110,152,.12));\r\n  user-select:none;\r\n}\r\n\r\n/* HERO */\r\n.kb-hero{\r\n  min-height:390px;\r\n  display:grid;\r\n  grid-template-columns:minmax(340px,39%) minmax(0,61%);\r\n  background:\r\n    radial-gradient(circle at 8% 18%,rgba(255,255,255,.95) 0 4px,transparent 5px),\r\n    radial-gradient(circle at 25% 78%,rgba(245,143,176,.22) 0 4px,transparent 5px),\r\n    linear-gradient(90deg,#fff7f9 0%,#ffedf3 43%,#ffe0e9 100%);\r\n  border:1px solid var(--kb-line);\r\n  border-radius:26px;\r\n  overflow:hidden;\r\n  position:relative;\r\n  box-shadow:var(--kb-shadow);\r\n}\r\n.kb-hero::before{\r\n  content:\"\";\r\n  position:absolute;\r\n  width:330px;height:330px;\r\n  border-radius:50%;\r\n  left:-140px;bottom:-210px;\r\n  border:26px solid rgba(255,255,255,.46);\r\n  box-shadow:0 0 0 22px rgba(255,255,255,.18);\r\n  animation:pulseHalo 6s ease-in-out infinite;\r\n}\r\n.kb-hero-copy{\r\n  position:relative;\r\n  z-index:3;\r\n  padding:42px 18px 40px 50px;\r\n  display:flex;\r\n  flex-direction:column;\r\n  justify-content:center;\r\n  align-items:flex-start;\r\n}\r\n.kb-kicker{\r\n  font-size:15px;\r\n  letter-spacing:.08em;\r\n  text-transform:uppercase;\r\n  color:var(--kb-pink-2);\r\n  font-weight:900;\r\n  margin-bottom:8px;\r\n  animation:slideInLeft .75s .05s both;\r\n}\r\n.kb-kicker .heart{display:inline-block;margin-left:6px;animation:heartBeat 1.9s infinite}\r\n.kb-hero h1{\r\n  margin:0;\r\n  color:#3f2b31;\r\n  font-family:\"Arial Rounded MT Bold\",\"Trebuchet MS\",sans-serif;\r\n  font-size:clamp(38px,4.2vw,58px);\r\n  line-height:1.01;\r\n  letter-spacing:-.045em;\r\n  font-weight:900;\r\n  animation:slideInLeft .85s .13s both;\r\n}\r\n.kb-hero h1 .pink{\r\n  color:var(--kb-pink-2);\r\n  text-shadow:0 4px 0 rgba(255,255,255,.72);\r\n}\r\n.kb-hero p{\r\n  font-size:14px;\r\n  line-height:1.6;\r\n  margin:19px 0 22px;\r\n  max-width:380px;\r\n  color:#513b42;\r\n  animation:slideInLeft .9s .22s both;\r\n}\r\n.kb-btn{\r\n  display:inline-flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  gap:8px;\r\n  border:0;\r\n  border-radius:999px;\r\n  padding:12px 24px;\r\n  font-weight:900;\r\n  font-size:14px;\r\n  cursor:pointer;\r\n  width:max-content;\r\n  position:relative;\r\n  overflow:hidden;\r\n  transition:transform .25s ease,box-shadow .25s ease,filter .25s ease;\r\n}\r\n.kb-btn::after{\r\n  content:\"\";\r\n  position:absolute;\r\n  top:-30%;\r\n  left:-35%;\r\n  width:28%;\r\n  height:160%;\r\n  background:rgba(255,255,255,.52);\r\n  transform:rotate(18deg);\r\n  transition:left .55s ease;\r\n}\r\n.kb-btn:hover::after{left:112%}\r\n.kb-btn:hover{transform:translateY(-3px) scale(1.015)}\r\n.kb-btn:active{transform:translateY(0) scale(.99)}\r\n.kb-btn-primary{\r\n  background:linear-gradient(135deg,#f79ab9,#ed5e90);\r\n  color:#fff;\r\n  box-shadow:0 10px 24px rgba(237,94,142,.24);\r\n  animation:slideInLeft .9s .3s both;\r\n}\r\n.kb-btn-primary:hover{box-shadow:0 14px 30px rgba(237,94,142,.31)}\r\n\r\n.kb-hero-art{\r\n  position:relative;\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:flex-end;\r\n  min-width:0;\r\n  overflow:hidden;\r\n}\r\n.kb-hero-art::before{\r\n  content:\"\";\r\n  position:absolute;\r\n  inset:0 auto 0 0;\r\n  width:92px;\r\n  background:linear-gradient(90deg,#ffedf3 4%,rgba(255,237,243,.78) 34%,transparent);\r\n  z-index:2;\r\n  pointer-events:none;\r\n}\r\n.kb-hero-art img{\r\n  width:100%;\r\n  height:100%;\r\n  object-fit:contain;\r\n  object-position:center right;\r\n  transform-origin:70% 60%;\r\n  animation:heroImageIn 1.1s cubic-bezier(.2,.8,.2,1) .12s both,heroFloat 5.5s ease-in-out 1.25s infinite;\r\n}\r\n.kb-sparkle{\r\n  position:absolute;\r\n  z-index:4;\r\n  color:#fff;\r\n  text-shadow:0 0 12px rgba(245,143,176,.7);\r\n  animation:twinkle 2.5s ease-in-out infinite;\r\n}\r\n.kb-s1{right:11%;top:11%;font-size:27px}\r\n.kb-s2{right:29%;bottom:15%;font-size:20px;animation-delay:.7s}\r\n.kb-s3{right:47%;top:26%;font-size:15px;animation-delay:1.4s}\r\n\r\n/* WORLD */\r\n.kb-world{\r\n  min-height:270px;\r\n  display:grid;\r\n  grid-template-columns:40% 60%;\r\n  align-items:center;\r\n  padding:16px 28px 16px 12px;\r\n}\r\n.kb-world-art{\r\n  height:235px;\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  overflow:visible;\r\n  padding:6px 8px;\r\n}\r\n.kb-world-art img{\r\n  width:100%;\r\n  height:100%;\r\n  object-fit:contain;\r\n  object-position:center;\r\n  animation:softFloat 5.2s ease-in-out infinite;\r\n  filter:drop-shadow(0 12px 18px rgba(197,83,124,.06));\r\n}\r\n.kb-world-copy{padding:10px 24px 10px 20px}\r\n.kb-title{\r\n  font-family:\"Arial Rounded MT Bold\",\"Trebuchet MS\",sans-serif;\r\n  font-size:clamp(24px,2.3vw,32px);\r\n  line-height:1.1;\r\n  color:#3e2c31;\r\n  text-align:center;\r\n  margin:0 0 16px;\r\n  font-weight:900;\r\n}\r\n.kb-title .decor{\r\n  color:var(--kb-pink);\r\n  font-size:.65em;\r\n  margin:0 10px;\r\n  display:inline-block;\r\n  animation:heartBeat 2s infinite;\r\n}\r\n.kb-points{list-style:none;margin:0;padding:0;display:grid;gap:11px}\r\n.kb-points li{\r\n  position:relative;\r\n  padding-left:30px;\r\n  font-size:13px;\r\n  line-height:1.45;\r\n  color:#4a383e;\r\n  opacity:0;\r\n  transform:translateX(12px);\r\n}\r\n.reveal.is-visible .kb-points li{animation:pointIn .48s ease forwards}\r\n.reveal.is-visible .kb-points li:nth-child(1){animation-delay:.12s}\r\n.reveal.is-visible .kb-points li:nth-child(2){animation-delay:.2s}\r\n.reveal.is-visible .kb-points li:nth-child(3){animation-delay:.28s}\r\n.reveal.is-visible .kb-points li:nth-child(4){animation-delay:.36s}\r\n.reveal.is-visible .kb-points li:nth-child(5){animation-delay:.44s}\r\n.kb-points li::before{\r\n  content:\"✓\";\r\n  position:absolute;\r\n  left:0;top:1px;\r\n  width:18px;height:18px;\r\n  border-radius:50%;\r\n  display:grid;\r\n  place-items:center;\r\n  background:linear-gradient(135deg,#f58fb0,#ed6e98);\r\n  color:#fff;\r\n  font-size:10px;\r\n  font-weight:900;\r\n  box-shadow:0 4px 10px rgba(237,110,152,.2);\r\n}\r\n\r\n/* BENEFITS */\r\n.kb-benefits{\r\n  display:grid;\r\n  grid-template-columns:repeat(4,minmax(0,1fr));\r\n  gap:12px;\r\n  margin-top:18px;\r\n}\r\n.kb-benefit{\r\n  min-height:154px;\r\n  background:rgba(255,255,255,.96);\r\n  border:1px solid var(--kb-line);\r\n  border-radius:20px;\r\n  padding:18px 15px;\r\n  display:grid;\r\n  grid-template-columns:82px 1fr;\r\n  gap:13px;\r\n  align-items:center;\r\n  transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease;\r\n  position:relative;\r\n  overflow:hidden;\r\n}\r\n.kb-benefit::before{\r\n  content:\"\";\r\n  position:absolute;\r\n  width:110px;height:110px;\r\n  border-radius:50%;\r\n  left:-54px;top:-56px;\r\n  background:radial-gradient(circle,rgba(245,143,176,.12),transparent 70%);\r\n}\r\n.kb-benefit:hover{\r\n  transform:translateY(-6px);\r\n  box-shadow:var(--kb-shadow-hover);\r\n  border-color:#f2b9cb;\r\n}\r\n.kb-benefit img{\r\n  width:82px;height:86px;\r\n  object-fit:contain;\r\n  object-position:center;\r\n  border-radius:16px;\r\n  transition:transform .35s ease;\r\n}\r\n.kb-benefit:hover img{transform:translateY(-4px) rotate(-2deg) scale(1.04)}\r\n.kb-benefit h3{font-size:13px;line-height:1.25;margin:0 0 8px;color:#3f2e34}\r\n.kb-benefit p{font-size:10.5px;line-height:1.5;margin:0;color:#554249}\r\n\r\n/* SOCIAL */\r\n.kb-social-title{margin:22px 0 10px}\r\n.kb-social-grid{\r\n  display:grid;\r\n  grid-template-columns:1fr 1fr;\r\n  gap:14px;\r\n  padding:0;\r\n}\r\n.kb-social{\r\n  min-height:185px;\r\n  border:1px solid var(--kb-line);\r\n  border-radius:22px;\r\n  overflow:hidden;\r\n  display:grid;\r\n  grid-template-columns:145px 1fr;\r\n  align-items:center;\r\n  gap:12px;\r\n  padding:18px 22px;\r\n  background:linear-gradient(135deg,#fff7f9,#ffe8ef);\r\n  box-shadow:var(--kb-shadow);\r\n  position:relative;\r\n  transition:transform .3s ease,box-shadow .3s ease;\r\n}\r\n.kb-social:hover{transform:translateY(-5px);box-shadow:var(--kb-shadow-hover)}\r\n.kb-social::after{\r\n  content:\"\";\r\n  position:absolute;\r\n  inset:auto -40px -55px auto;\r\n  width:150px;height:150px;\r\n  border-radius:50%;\r\n  background:rgba(255,255,255,.35);\r\n}\r\n.kb-social.tiktok{\r\n  background:linear-gradient(135deg,#fff8fc,#f5e8fa);\r\n  border-color:#ead6ef;\r\n}\r\n.kb-social img{\r\n  width:135px;height:125px;\r\n  object-fit:contain;\r\n  object-position:center;\r\n  border-radius:18px;\r\n  transition:transform .35s ease;\r\n}\r\n.kb-social:hover img{transform:scale(1.04) rotate(-2deg)}\r\n.kb-social h3{\r\n  margin:0 0 8px;\r\n  font-size:21px;\r\n  line-height:1.08;\r\n  color:#ed5e90;\r\n  font-family:\"Arial Rounded MT Bold\",\"Trebuchet MS\",sans-serif;\r\n}\r\n.kb-social.tiktok h3{color:#9857aa}\r\n.kb-social p{font-size:11.5px;line-height:1.5;margin:0 0 12px;color:#523f46;max-width:300px}\r\n.kb-btn-sm{font-size:11px;padding:9px 17px}\r\n.kb-btn-tiktok{\r\n  background:linear-gradient(135deg,#ba75c4,#9e5fb3);\r\n  color:#fff;\r\n  box-shadow:0 8px 18px rgba(158,95,179,.16);\r\n}\r\n\r\n/* DISCLOSURE */\r\n.kb-disclosure{\r\n  margin:16px 0 0;\r\n  border:1px solid var(--kb-line);\r\n  border-radius:18px;\r\n  padding:20px 26px;\r\n  background:linear-gradient(90deg,#fffaf9,#fff2f6,#fffaf9);\r\n  position:relative;\r\n  text-align:center;\r\n  overflow:hidden;\r\n}\r\n.kb-disclosure::before{\r\n  content:\"\";\r\n  position:absolute;\r\n  inset:7px;\r\n  border:1px dashed #f0aec4;\r\n  border-radius:13px;\r\n  pointer-events:none;\r\n  animation:dashGlow 3.3s ease-in-out infinite;\r\n}\r\n.kb-disclosure::after{\r\n  content:\"♡\";\r\n  position:absolute;\r\n  right:24px;top:50%;\r\n  transform:translateY(-50%);\r\n  font-size:24px;color:#f1a1ba;\r\n  animation:heartBeat 2s infinite;\r\n}\r\n.kb-disclosure strong{display:block;font-size:12px;color:#403037;position:relative;z-index:1}\r\n.kb-disclosure span{font-size:10.5px;color:#665158;position:relative;z-index:1}\r\n\r\n/* CONTACT */\r\n.kb-contact{\r\n  margin-top:16px;\r\n  min-height:138px;\r\n  border:1px solid var(--kb-line);\r\n  border-radius:22px;\r\n  background:linear-gradient(90deg,#fff8fa,#fff0f5);\r\n  display:grid;\r\n  grid-template-columns:24% 38% 38%;\r\n  align-items:center;\r\n  overflow:hidden;\r\n  box-shadow:var(--kb-shadow);\r\n  position:relative;\r\n}\r\n.kb-contact-art{\r\n  height:136px;\r\n  display:flex;\r\n  align-items:center;\r\n  justify-content:center;\r\n  overflow:visible;\r\n  padding:8px 10px;\r\n}\r\n.kb-contact-art img{\r\n  width:100%;\r\n  height:100%;\r\n  object-fit:contain;\r\n  object-position:center;\r\n  animation:contactFloat 4s ease-in-out infinite;\r\n}\r\n.kb-contact-copy{padding:18px 24px;border-right:1px solid #efc9d5}\r\n.kb-contact-copy h2{\r\n  font-family:\"Arial Rounded MT Bold\",\"Trebuchet MS\",sans-serif;\r\n  margin:0 0 8px;\r\n  font-size:30px;\r\n  color:#33252a;\r\n}\r\n.kb-contact-copy p{font-size:11px;line-height:1.5;margin:0;color:#5b454d}\r\n.kb-contact-action{\r\n  display:flex;\r\n  flex-direction:column;\r\n  align-items:flex-start;\r\n  justify-content:center;\r\n  padding:18px 30px;\r\n  gap:14px;\r\n}\r\n.kb-email{\r\n  font-size:14px;\r\n  font-weight:900;\r\n  color:#3d2c32;\r\n  display:flex;\r\n  align-items:center;\r\n  gap:10px;\r\n  transition:color .2s ease;\r\n}\r\n.kb-email:hover{color:var(--kb-pink-2)}\r\n.kb-mail-icon{\r\n  width:27px;height:20px;\r\n  border:2px solid #ee7198;\r\n  border-radius:4px;\r\n  position:relative;\r\n  flex:0 0 auto;\r\n  animation:mailWiggle 4s ease-in-out infinite;\r\n}\r\n.kb-mail-icon::before{\r\n  content:\"\";\r\n  position:absolute;\r\n  left:4px;right:4px;top:0;\r\n  height:9px;\r\n  border-left:2px solid #ee7198;\r\n  border-bottom:2px solid #ee7198;\r\n  transform:rotate(-45deg) skew(4deg);\r\n}\r\n.kb-contact .kb-btn{min-width:160px}\r\n\r\n/* Scroll reveal */\r\n.reveal{\r\n  opacity:0;\r\n  transform:translateY(26px) scale(.99);\r\n  transition:\r\n    opacity .72s cubic-bezier(.2,.8,.2,1),\r\n    transform .72s cubic-bezier(.2,.8,.2,1);\r\n}\r\n.reveal.is-visible{opacity:1;transform:none}\r\n.kb-benefits.reveal.is-visible .kb-benefit{animation:benefitPop .6s both}\r\n.kb-benefits.reveal.is-visible .kb-benefit:nth-child(1){animation-delay:.05s}\r\n.kb-benefits.reveal.is-visible .kb-benefit:nth-child(2){animation-delay:.13s}\r\n.kb-benefits.reveal.is-visible .kb-benefit:nth-child(3){animation-delay:.21s}\r\n.kb-benefits.reveal.is-visible .kb-benefit:nth-child(4){animation-delay:.29s}\r\n.kb-social-grid .kb-social{opacity:0;transform:translateY(18px)}\r\n.reveal.is-visible .kb-social:nth-child(1){animation:socialIn .62s .08s both}\r\n.reveal.is-visible .kb-social:nth-child(2){animation:socialIn .62s .18s both}\r\n\r\n/* Keyframes */\r\n@keyframes slideInLeft{from{opacity:0;transform:translateX(-28px)}to{opacity:1;transform:none}}\r\n@keyframes heroImageIn{from{opacity:0;transform:translateX(44px) scale(.97)}to{opacity:1;transform:none}}\r\n@keyframes heroFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}\r\n@keyframes softFloat{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-5px) rotate(.4deg)}}\r\n@keyframes contactFloat{0%,100%{transform:translateY(0) rotate(-1deg)}50%{transform:translateY(-5px) rotate(1deg)}}\r\n@keyframes pointIn{to{opacity:1;transform:none}}\r\n@keyframes benefitPop{from{opacity:0;transform:translateY(18px) scale(.97)}to{opacity:1;transform:none}}\r\n@keyframes socialIn{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}\r\n@keyframes heartBeat{0%,100%{transform:scale(1)}45%{transform:scale(1.18)}60%{transform:scale(.98)}}\r\n@keyframes twinkle{0%,100%{opacity:.28;transform:scale(.75) rotate(0)}50%{opacity:1;transform:scale(1.15) rotate(18deg)}}\r\n@keyframes pulseHalo{0%,100%{opacity:.5;transform:scale(1)}50%{opacity:.72;transform:scale(1.04)}}\r\n@keyframes mailWiggle{0%,88%,100%{transform:rotate(0)}92%{transform:rotate(-5deg)}96%{transform:rotate(5deg)}}\r\n@keyframes dashGlow{0%,100%{opacity:.6}50%{opacity:1;box-shadow:inset 0 0 14px rgba(245,143,176,.08)}}\r\n@keyframes drift{from{transform:translate3d(0,0,0) rotate(-5deg)}to{transform:translate3d(var(--dx),var(--dy),0) rotate(8deg)}}\r\n@keyframes cardSweep{from{transform:translateX(-130%)}to{transform:translateX(130%)}}\r\n\r\n@media (max-width:980px){\r\n  .kb-page{width:min(100% - 26px,900px);padding-top:20px}\r\n  .kb-hero{grid-template-columns:42% 58%;min-height:360px}\r\n  .kb-hero-copy{padding:34px 14px 34px 34px}\r\n  .kb-world{grid-template-columns:39% 61%;padding-right:18px}\r\n  .kb-benefit{grid-template-columns:70px 1fr;padding:15px 12px}\r\n  .kb-benefit img{width:70px;height:76px}\r\n  .kb-social{grid-template-columns:120px 1fr;padding:16px}\r\n  .kb-social img{width:115px;height:110px}\r\n}\r\n\r\n@media (max-width:800px){\r\n  .kb-page{width:min(100% - 24px,720px);padding-top:16px}\r\n  .kb-hero{grid-template-columns:1fr;min-height:0}\r\n  .kb-hero-copy{padding:34px 28px 22px;align-items:center;text-align:center}\r\n  .kb-hero p{max-width:560px}\r\n  .kb-hero-art{height:auto;min-height:280px}\r\n  .kb-hero-art::before{display:none}\r\n  .kb-hero-art img{height:auto;max-height:390px;object-fit:contain;object-position:center}\r\n  .kb-world{grid-template-columns:1fr;padding:15px 20px 24px}\r\n  .kb-world-art{height:auto;min-height:220px;max-height:270px}\r\n  .kb-world-art img{max-height:255px}\r\n  .kb-world-copy{padding:0 12px 4px}\r\n  .kb-benefits{grid-template-columns:1fr 1fr}\r\n  .kb-social-grid{grid-template-columns:1fr}\r\n  .kb-contact{grid-template-columns:1fr;text-align:center;padding-bottom:20px}\r\n  .kb-contact-art{height:125px}\r\n  .kb-contact-art img{max-width:240px}\r\n  .kb-contact-copy{border-right:0;padding:0 26px 14px}\r\n  .kb-contact-action{align-items:center;padding:7px 20px}\r\n}\r\n\r\n@media (max-width:560px){\r\n  .kb-page{width:calc(100% - 18px);padding-top:10px}\r\n  .kb-hero{border-radius:20px}\r\n  .kb-hero-copy{padding:28px 18px 18px}\r\n  .kb-hero h1{font-size:36px}\r\n  .kb-hero p{font-size:13px}\r\n  .kb-hero-art{min-height:220px}\r\n  .kb-world{padding-left:12px;padding-right:12px}\r\n  .kb-world-art{min-height:185px}\r\n  .kb-benefits{grid-template-columns:1fr}\r\n  .kb-benefit{min-height:120px;grid-template-columns:78px 1fr}\r\n  .kb-benefit img{width:76px;height:80px}\r\n  .kb-social{grid-template-columns:95px 1fr;gap:9px;padding:14px}\r\n  .kb-social img{width:92px;height:96px}\r\n  .kb-social h3{font-size:17px}\r\n  .kb-disclosure{padding:20px 34px 20px 18px}\r\n  .kb-disclosure::after{right:12px}\r\n  .kb-email{font-size:12px}\r\n}\r\n\r\n@media (prefers-reduced-motion:reduce){\r\n  *,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}\r\n  .reveal,.kb-social-grid .kb-social,.kb-points li{opacity:1!important;transform:none!important}\r\n}\r\n\r\n/* VIDEO SECTION */\r\n.kb-video-section{\r\n  margin:20px 0;\r\n  display:flex;\r\n  justify-content:center;\r\n}\r\n.kb-video-frame{\r\n  width:100%;\r\n  max-width:100%;\r\n  border-radius:24px;\r\n  overflow:hidden;\r\n  border:1px solid var(--kb-line);\r\n  background:rgba(255,255,255,.95);\r\n  box-shadow:0 14px 40px rgba(197,83,124,.10);\r\n  line-height:0;\r\n}\r\n.kb-video{\r\n  width:100%;\r\n  height:auto;\r\n  display:block;\r\n  border-radius:23px;\r\n  object-fit:cover;\r\n}\r\n\r\n\r\n/* =========================================================\r\n   KAWAII BUNNY PEEK SCROLL EFFECT\r\n   Adds animated bunny heads that peek from behind cards/sections\r\n   as each section enters the viewport.\r\n   ========================================================= */\r\n\r\n.kb-bunny-host {\r\n    position: relative !important;\r\n    isolation: isolate;\r\n    overflow: visible !important;\r\n}\r\n\r\n.kb-bunny-host > *:not(.kb-bunny-peek) {\r\n    position: relative;\r\n    z-index: 2;\r\n}\r\n\r\n.kb-bunny-peek {\r\n    --peek: 0;\r\n    --size: 84px;\r\n    --bob: 0px;\r\n\r\n    position: absolute;\r\n    top: 50%;\r\n    width: var(--size);\r\n    height: calc(var(--size) * 1.06);\r\n    pointer-events: none;\r\n    z-index: 1;\r\n    opacity: calc(0.04 + (var(--peek) * 0.96));\r\n    filter: drop-shadow(0 8px 18px rgba(215, 144, 165, .14));\r\n    transition:\r\n        opacity .22s ease,\r\n        filter .25s ease;\r\n}\r\n\r\n.kb-bunny-peek.left {\r\n    left: 0;\r\n    transform:\r\n        translate(\r\n            calc((-56% + (var(--peek) * 42%))),\r\n            calc(-50% + var(--bob))\r\n        );\r\n}\r\n\r\n.kb-bunny-peek.right {\r\n    right: 0;\r\n    transform:\r\n        translate(\r\n            calc((56% - (var(--peek) * 42%))),\r\n            calc(-50% + var(--bob))\r\n        );\r\n}\r\n\r\n.kb-bunny-peek .bunny-shadow {\r\n    position: absolute;\r\n    left: 50%;\r\n    bottom: 6px;\r\n    width: 62%;\r\n    height: 12px;\r\n    border-radius: 999px;\r\n    background: radial-gradient(ellipse at center, rgba(225, 153, 176, .24), transparent 70%);\r\n    transform: translateX(-50%);\r\n    opacity: calc(.18 + (var(--peek) * .32));\r\n}\r\n\r\n.kb-bunny-peek .ear {\r\n    position: absolute;\r\n    top: 1px;\r\n    width: 23px;\r\n    height: 44px;\r\n    border-radius: 20px 20px 15px 15px;\r\n    background: linear-gradient(180deg, #fffefe 0%, #fff4f7 100%);\r\n    border: 1px solid rgba(239, 205, 216, .95);\r\n    box-shadow: inset 0 1px 0 rgba(255,255,255,.94);\r\n}\r\n\r\n.kb-bunny-peek .ear::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    inset: 6px 5px 8px;\r\n    border-radius: 18px;\r\n    background: linear-gradient(180deg, rgba(247, 177, 199, .92), rgba(243, 150, 182, .70));\r\n    opacity: .9;\r\n}\r\n\r\n.kb-bunny-peek.left .ear-left,\r\n.kb-bunny-peek.right .ear-left {\r\n    left: 19px;\r\n    transform: rotate(-10deg);\r\n}\r\n\r\n.kb-bunny-peek.left .ear-right,\r\n.kb-bunny-peek.right .ear-right {\r\n    right: 19px;\r\n    transform: rotate(10deg);\r\n}\r\n\r\n.kb-bunny-peek .head {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 24px;\r\n    width: 68px;\r\n    height: 57px;\r\n    transform: translateX(-50%);\r\n    border-radius: 50% 50% 44% 44%;\r\n    background: linear-gradient(180deg, #fffefe 0%, #fff7fa 100%);\r\n    border: 1px solid rgba(239, 205, 216, .95);\r\n    box-shadow:\r\n        inset 0 1px 0 rgba(255,255,255,.96),\r\n        0 2px 10px rgba(225, 155, 176, .05);\r\n}\r\n\r\n.kb-bunny-peek .cheek {\r\n    position: absolute;\r\n    top: 30px;\r\n    width: 10px;\r\n    height: 8px;\r\n    border-radius: 50%;\r\n    background: rgba(247, 174, 196, .55);\r\n    filter: blur(.4px);\r\n}\r\n\r\n.kb-bunny-peek .cheek.left-cheek {\r\n    left: 14px;\r\n}\r\n\r\n.kb-bunny-peek .cheek.right-cheek {\r\n    right: 14px;\r\n}\r\n\r\n.kb-bunny-peek .eye {\r\n    position: absolute;\r\n    top: 21px;\r\n    width: 5px;\r\n    height: 7px;\r\n    border-radius: 999px;\r\n    background: #7c5a66;\r\n    animation: kbBunnyBlink 5.6s infinite;\r\n}\r\n\r\n.kb-bunny-peek .eye.left-eye {\r\n    left: 22px;\r\n}\r\n\r\n.kb-bunny-peek .eye.right-eye {\r\n    right: 22px;\r\n}\r\n\r\n.kb-bunny-peek .nose {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 28px;\r\n    width: 8px;\r\n    height: 6px;\r\n    transform: translateX(-50%);\r\n    border-radius: 50% 50% 60% 60%;\r\n    background: #f39ab8;\r\n}\r\n\r\n.kb-bunny-peek .mouth {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 34px;\r\n    width: 15px;\r\n    height: 9px;\r\n    transform: translateX(-50%);\r\n}\r\n\r\n.kb-bunny-peek .mouth::before,\r\n.kb-bunny-peek .mouth::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    top: 0;\r\n    width: 7px;\r\n    height: 7px;\r\n    border-bottom: 1.6px solid #9a7480;\r\n    border-radius: 0 0 10px 10px;\r\n}\r\n\r\n.kb-bunny-peek .mouth::before {\r\n    left: 0;\r\n    border-left: 1.2px solid transparent;\r\n    transform: rotate(8deg);\r\n}\r\n\r\n.kb-bunny-peek .mouth::after {\r\n    right: 0;\r\n    border-right: 1.2px solid transparent;\r\n    transform: rotate(-8deg);\r\n}\r\n\r\n.kb-bunny-peek .paw {\r\n    position: absolute;\r\n    bottom: -2px;\r\n    width: 18px;\r\n    height: 16px;\r\n    border-radius: 50% 50% 45% 45%;\r\n    background: linear-gradient(180deg, #fffefe 0%, #fff4f7 100%);\r\n    border: 1px solid rgba(239, 205, 216, .95);\r\n}\r\n\r\n.kb-bunny-peek.left .paw-left,\r\n.kb-bunny-peek.right .paw-left {\r\n    left: 18px;\r\n}\r\n\r\n.kb-bunny-peek.left .paw-right,\r\n.kb-bunny-peek.right .paw-right {\r\n    right: 18px;\r\n}\r\n\r\n.kb-bunny-peek .sparkle {\r\n    position: absolute;\r\n    color: rgba(214, 171, 84, .85);\r\n    font-size: 12px;\r\n    opacity: calc(.12 + (var(--peek) * .88));\r\n    animation: kbBunnySparkle 3.4s ease-in-out infinite;\r\n}\r\n\r\n.kb-bunny-peek .sparkle.s1 { top: 17px; left: 3px; }\r\n.kb-bunny-peek .sparkle.s2 { top: 10px; right: 4px; animation-delay: 1.2s; }\r\n\r\n@keyframes kbBunnyBlink {\r\n    0%, 43%, 47%, 100% { transform: scaleY(1); }\r\n    45% { transform: scaleY(.15); }\r\n}\r\n\r\n@keyframes kbBunnySparkle {\r\n    0%, 100% { transform: scale(.78) rotate(0deg); opacity: .22; }\r\n    50% { transform: scale(1.15) rotate(18deg); opacity: .92; }\r\n}\r\n\r\n@media (max-width: 780px) {\r\n    .kb-bunny-peek {\r\n        --size: 68px;\r\n    }\r\n}\r\n\r\n@media (max-width: 520px) {\r\n    .kb-bunny-peek {\r\n        --size: 58px;\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .kb-bunny-peek,\r\n    .kb-bunny-peek * {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n\r\n</style>\r\n\r\n<style>\r\n/* =========================================================\r\n   BUNNY PEEK EFFECT — FIXED + STYLED VARIANTS\r\n   This version avoids unsupported CSS math, so the mascots\r\n   actually appear on scroll. Each major section gets its\r\n   own original mascot style with a soft nod to kawaii\r\n   character archetypes.\r\n   ========================================================= */\r\n\r\n.kb-bunny-host {\r\n    position: relative !important;\r\n    isolation: isolate;\r\n    overflow: visible !important;\r\n}\r\n\r\n.kb-bunny-host > *:not(.kb-bunny-peek) {\r\n    position: relative;\r\n    z-index: 2;\r\n}\r\n\r\n.kb-bunny-peek {\r\n    --size: 92px;\r\n    --hood-1: #ffd4e1;\r\n    --hood-2: #f7adc7;\r\n    --ear-inner: #f4abc4;\r\n    --accent: #e67ea4;\r\n    --accent-2: #d9b357;\r\n    --cheek: rgba(244, 170, 193, .58);\r\n    --outline: rgba(236, 204, 215, .98);\r\n    --shadow: rgba(212, 140, 165, .18);\r\n    --eye: #735862;\r\n\r\n    position: absolute;\r\n    top: 50%;\r\n    width: var(--size);\r\n    height: calc(var(--size) * 1.08);\r\n    pointer-events: none;\r\n    z-index: 1;\r\n\r\n    opacity: 0;\r\n    transform: translate(-62%, -50%);\r\n    will-change: transform, opacity;\r\n    filter: drop-shadow(0 10px 20px rgba(215, 144, 165, .12));\r\n    transition:\r\n        opacity .16s linear,\r\n        filter .22s ease;\r\n}\r\n\r\n.kb-bunny-peek.right {\r\n    transform: translate(62%, -50%);\r\n}\r\n\r\n.kb-bunny-peek .bunny-shadow {\r\n    position: absolute;\r\n    left: 50%;\r\n    bottom: 4px;\r\n    width: 64%;\r\n    height: 11px;\r\n    border-radius: 999px;\r\n    background: radial-gradient(ellipse at center, rgba(224, 151, 175, .24), transparent 72%);\r\n    transform: translateX(-50%);\r\n    opacity: .38;\r\n}\r\n\r\n.kb-bunny-peek .ear {\r\n    position: absolute;\r\n    top: 1px;\r\n    width: 24px;\r\n    height: 47px;\r\n    border-radius: 22px 22px 15px 15px;\r\n    background: linear-gradient(180deg, #fffefe 0%, #fff5f8 100%);\r\n    border: 1px solid var(--outline);\r\n    box-shadow: inset 0 1px 0 rgba(255,255,255,.96);\r\n}\r\n\r\n.kb-bunny-peek .ear::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    inset: 6px 5px 8px;\r\n    border-radius: 18px;\r\n    background: linear-gradient(180deg, var(--ear-inner) 0%, rgba(244, 151, 183, .74) 100%);\r\n}\r\n\r\n.kb-bunny-peek .ear-left {\r\n    left: 18px;\r\n    transform: rotate(-11deg);\r\n}\r\n\r\n.kb-bunny-peek .ear-right {\r\n    right: 18px;\r\n    transform: rotate(11deg);\r\n}\r\n\r\n.kb-bunny-peek .hood {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 17px;\r\n    width: 76px;\r\n    height: 61px;\r\n    transform: translateX(-50%);\r\n    border-radius: 52% 52% 45% 45%;\r\n    background: linear-gradient(180deg, var(--hood-1) 0%, var(--hood-2) 100%);\r\n    border: 1px solid rgba(229, 189, 203, .92);\r\n    box-shadow: inset 0 1px 0 rgba(255,255,255,.50);\r\n}\r\n\r\n.kb-bunny-peek .head {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 24px;\r\n    width: 68px;\r\n    height: 57px;\r\n    transform: translateX(-50%);\r\n    border-radius: 50% 50% 44% 44%;\r\n    background: linear-gradient(180deg, #fffefe 0%, #fff7fa 100%);\r\n    border: 1px solid var(--outline);\r\n    box-shadow:\r\n        inset 0 1px 0 rgba(255,255,255,.96),\r\n        0 2px 10px rgba(225, 155, 176, .05);\r\n}\r\n\r\n.kb-bunny-peek .cheek {\r\n    position: absolute;\r\n    top: 30px;\r\n    width: 10px;\r\n    height: 8px;\r\n    border-radius: 50%;\r\n    background: var(--cheek);\r\n    filter: blur(.4px);\r\n}\r\n.kb-bunny-peek .left-cheek { left: 14px; }\r\n.kb-bunny-peek .right-cheek { right: 14px; }\r\n\r\n.kb-bunny-peek .eye {\r\n    position: absolute;\r\n    top: 21px;\r\n    width: 5px;\r\n    height: 7px;\r\n    border-radius: 999px;\r\n    background: var(--eye);\r\n    transform-origin: center;\r\n    animation: kbBunnyBlink 5.4s infinite;\r\n}\r\n.kb-bunny-peek .left-eye { left: 22px; }\r\n.kb-bunny-peek .right-eye { right: 22px; }\r\n\r\n.kb-bunny-peek .nose {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 28px;\r\n    width: 8px;\r\n    height: 6px;\r\n    transform: translateX(-50%);\r\n    border-radius: 50% 50% 60% 60%;\r\n    background: #f39ab8;\r\n}\r\n\r\n.kb-bunny-peek .mouth {\r\n    position: absolute;\r\n    left: 50%;\r\n    top: 34px;\r\n    width: 15px;\r\n    height: 9px;\r\n    transform: translateX(-50%);\r\n}\r\n.kb-bunny-peek .mouth::before,\r\n.kb-bunny-peek .mouth::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    top: 0;\r\n    width: 7px;\r\n    height: 7px;\r\n    border-bottom: 1.6px solid #9a7480;\r\n    border-radius: 0 0 10px 10px;\r\n}\r\n.kb-bunny-peek .mouth::before {\r\n    left: 0;\r\n    transform: rotate(8deg);\r\n}\r\n.kb-bunny-peek .mouth::after {\r\n    right: 0;\r\n    transform: rotate(-8deg);\r\n}\r\n\r\n.kb-bunny-peek .paw {\r\n    position: absolute;\r\n    bottom: -1px;\r\n    width: 18px;\r\n    height: 16px;\r\n    border-radius: 50% 50% 45% 45%;\r\n    background: linear-gradient(180deg, #fffefe 0%, #fff4f7 100%);\r\n    border: 1px solid var(--outline);\r\n}\r\n.kb-bunny-peek .paw-left { left: 18px; }\r\n.kb-bunny-peek .paw-right { right: 18px; }\r\n\r\n.kb-bunny-peek .badge {\r\n    position: absolute;\r\n    z-index: 6;\r\n    left: 50%;\r\n    top: 18px;\r\n    min-width: 20px;\r\n    height: 20px;\r\n    padding: 0 6px;\r\n    transform: translateX(-50%);\r\n    border-radius: 999px;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 11px;\r\n    font-weight: 800;\r\n    line-height: 1;\r\n    background: rgba(255,255,255,.82);\r\n    color: var(--accent);\r\n    box-shadow: 0 3px 10px rgba(219, 162, 78, .10);\r\n}\r\n\r\n.kb-bunny-peek .sparkle {\r\n    position: absolute;\r\n    color: rgba(214, 171, 84, .92);\r\n    font-size: 12px;\r\n    animation: kbBunnySparkle 3.2s ease-in-out infinite;\r\n}\r\n.kb-bunny-peek .s1 { top: 17px; left: 3px; }\r\n.kb-bunny-peek .s2 { top: 10px; right: 4px; animation-delay: 1.15s; }\r\n\r\n/* variant: rosy ribbon bunny (soft My Melody-ish mood) */\r\n.kb-bunny-peek.theme-rose {\r\n    --hood-1: #ffd6e6;\r\n    --hood-2: #f7a9c7;\r\n    --ear-inner: #f7b2ca;\r\n    --accent: #e97aa3;\r\n}\r\n.kb-bunny-peek.theme-rose .badge { color: #e97aa3; }\r\n\r\n/* variant: mint garden bunny */\r\n.kb-bunny-peek.theme-mint {\r\n    --hood-1: #dff7ee;\r\n    --hood-2: #b7e7d5;\r\n    --ear-inner: #b6e2cf;\r\n    --accent: #62aa8b;\r\n    --cheek: rgba(245, 176, 194, .50);\r\n}\r\n.kb-bunny-peek.theme-mint .badge { color: #62aa8b; }\r\n\r\n/* variant: plum mischief bunny (original, Kuromi-adjacent mood) */\r\n.kb-bunny-peek.theme-plum {\r\n    --hood-1: #e2d6ff;\r\n    --hood-2: #b7a1ea;\r\n    --ear-inner: #d4bdf9;\r\n    --accent: #7b5abf;\r\n    --eye: #5e506d;\r\n}\r\n.kb-bunny-peek.theme-plum .hood {\r\n    border-radius: 46% 46% 45% 45%;\r\n}\r\n.kb-bunny-peek.theme-plum .badge { color: #7b5abf; }\r\n\r\n/* variant: cream angel bunny */\r\n.kb-bunny-peek.theme-cream {\r\n    --hood-1: #fff4dd;\r\n    --hood-2: #f6dfac;\r\n    --ear-inner: #f0d8a2;\r\n    --accent: #c2933d;\r\n    --accent-2: #e5c16c;\r\n}\r\n.kb-bunny-peek.theme-cream .badge { color: #c2933d; }\r\n\r\n@keyframes kbBunnyBlink {\r\n    0%, 42%, 47%, 100% { transform: scaleY(1); }\r\n    44.5% { transform: scaleY(.12); }\r\n}\r\n\r\n@keyframes kbBunnySparkle {\r\n    0%, 100% { transform: scale(.78) rotate(0deg); opacity: .28; }\r\n    50% { transform: scale(1.12) rotate(18deg); opacity: .95; }\r\n}\r\n\r\n@media (max-width: 780px) {\r\n    .kb-bunny-peek { --size: 74px; }\r\n}\r\n@media (max-width: 520px) {\r\n    .kb-bunny-peek { --size: 60px; }\r\n}\r\n@media (prefers-reduced-motion: reduce) {\r\n    .kb-bunny-peek,\r\n    .kb-bunny-peek * {\r\n        animation: none !important;\r\n        transition: none !important;\r\n    }\r\n}\r\n</style>\r\n\r\n\r\n<style>\r\n/* =========================================================\r\n   VIEWPORT CORNER PEEK MASCOTS\r\n   Fixed to page corners so they stay visible and are not\r\n   clipped by section/card overflow.\r\n   ========================================================= */\r\n\r\n#kb-corner-peek-layer {\r\n    position: fixed;\r\n    inset: 0;\r\n    z-index: 9999;\r\n    pointer-events: none;\r\n}\r\n\r\n.kb-corner-peeker {\r\n    --size: 118px;\r\n    --hood-1: #ffd8e6;\r\n    --hood-2: #f6abc7;\r\n    --ear-inner: #f4b0c9;\r\n    --eye: #6d5761;\r\n    --accent: #e979a3;\r\n    --accent-2: #d8b05b;\r\n    --cheek: rgba(244, 167, 191, .58);\r\n    --outline: rgba(238, 207, 217, .98);\r\n    --white: #fffdfd;\r\n\r\n    position: fixed;\r\n    width: var(--size);\r\n    height: calc(var(--size) * 1.15);\r\n    bottom: 12px;\r\n    opacity: 0;\r\n    pointer-events: none;\r\n    will-change: transform, opacity;\r\n    transition: opacity .22s ease, filter .25s ease;\r\n    filter: drop-shadow(0 12px 24px rgba(214, 144, 164, .12));\r\n}\r\n\r\n.kb-corner-peeker.left {\r\n    left: 10px;\r\n    transform: translate(-88px, 10px) scale(.96);\r\n}\r\n\r\n.kb-corner-peeker.right {\r\n    right: 10px;\r\n    transform: translate(88px, 10px) scale(.96);\r\n}\r\n\r\n.kb-corner-peeker .shadow {\r\n    position: absolute;\r\n    left: 50%;\r\n    bottom: 2px;\r\n    width: 65%;\r\n    height: 14px;\r\n    transform: translateX(-50%);\r\n    border-radius: 999px;\r\n    background: radial-gradient(ellipse at center, rgba(223, 152, 174, .22), transparent 72%);\r\n}\r\n\r\n.kb-corner-peeker .ear {\r\n    position: absolute;\r\n    top: 2px;\r\n    width: 28px;\r\n    height: 55px;\r\n    border-radius: 22px 22px 16px 16px;\r\n    background: linear-gradient(180deg, var(--white) 0%, #fff3f8 100%);\r\n    border: 1px solid var(--outline);\r\n    bo