LL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(32,'sales.taxes.default_destination_calculation.post_code','',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(33,'sales.taxes.shopping_cart.display_prices','excluding_tax',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(34,'sales.taxes.shopping_cart.display_subtotal','excluding_tax',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(35,'sales.taxes.shopping_cart.display_shipping_amount','excluding_tax',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(36,'sales.taxes.shopping_cart.show_tax_breakdown','0',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(37,'sales.taxes.sales.display_prices','excluding_tax',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(38,'sales.taxes.sales.display_subtotal','excluding_tax',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(39,'sales.taxes.sales.display_shipping_amount','excluding_tax',NULL,NULL,'2026-08-27 12:08:48','2026-08-27 12:08:48'),(40,'magic_ai.general.settings.enabled','1',NULL,NULL,'2026-08-27 12:09:54','2026-08-27 12:09:54'),(41,'magic_ai.admin_features.text_generation.enabled','1',NULL,NULL,'2026-08-27 12:10:16','2026-08-27 12:10:16'),(42,'magic_ai.admin_features.image_generation.enabled','0',NULL,NULL,'2026-08-27 12:10:16','2026-08-27 12:10:16'),(43,'general.gdpr.settings.enabled','1','default','en','2026-08-27 12:12:02','2026-08-27 12:12:02'),(44,'general.gdpr.agreement.enabled','0','default','en','2026-08-27 12:12:02','2026-08-27 12:12:02'),(45,'general.gdpr.cookie.enabled','1','default','en','2026-08-27 12:12:02','2026-08-27 12:12:02'),(46,'general.gdpr.cookie.position','bottom-left','default','en','2026-08-27 12:12:02','2026-08-27 12:12:02'),(47,'general.gdpr.cookie.static_block_identifier','Cookie Block','default','en','2026-08-27 12:12:02','2026-08-27 12:12:02'),(48,'general.gdpr.cookie.description','This website uses cookies to ensure you get the best experience on our website.','default','en','2026-08-27 12:12:0