INSERT INTO `product_attribute_values` VALUES (1,'en',NULL,'<p class=\"PDq2pG_selectionAnchorContainer\">Add a little Love and Deepspace charm to your everyday look with these adorable plush bag charms. Soft, cute and perfect for handbags, backpacks, totes, keys or gifting to fellow fans. 💕✨</p>\n<p> </p>',NULL,NULL,NULL,NULL,NULL,NULL,1,9,'en|1|9'),(2,'en',NULL,'<p class=\"PDq2pG_selectionAnchorContainer\">Bring your favourite <strong>Love and Deepspace</strong> aesthetic wherever you go with these super-cute plush bag charms. Designed to add personality to handbags, backpacks, totes, pouches and more, each charm combines a soft plush finish with an irresistibly collectible kawaii look.</p>\n<p>Perfect for fans who love decorating their bags with character-inspired accessories, these plush charms also make a sweet gift for birthdays, special occasions or simply as a little treat for yourself.</p>\n<p>Whether you attach one to your everyday bag, display it with your collection or gift it to another Love and Deepspace fan, it is an adorable way to carry a little extra cuteness everywhere. 💖</p>\n<p><strong>Perfect for:</strong> handbags, backpacks, tote bags, pouches, keys, collections and gifting.</p>\n<p><em>Please refer to the product images and available variants for individual character/design details.</em></p>',NULL,NULL,NULL,NULL,NULL,NULL,1,10,'en|1|10'),(3,NULL,NULL,'1',NULL,NULL,NULL,NULL,NULL,NULL,1,1,'1|1'),(4,'en',NULL,'Love and deepspace bag charm Plushes',NULL,NULL,NULL,NULL,NULL,NULL,1,2,'en|1|2'),(5,'en',NULL,'love-and-deepspace-bag-charm-plushes',NULL,NULL,NULL,NULL,NULL,NULL,1,3,'en|1|3'),(6,NULL,'default',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,4,'default|1|4'),(7,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,23,'1|23'),(8,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,24,'1|24'),(9,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,25,'1|25'),(10,NULL,NULL,'1',NULL,NULL,NULL,NULL,NULL,NULL,1,27,'1|27'),(11,NULL,'default',NULL,0,NULL,NULL,NULL,NULL,NULL,1,28,'default|1|28'),(12,'en',NULL,'Love and Deepspace Bag Charm Plushes UAE | Kawaii Blessings',NULL,NULL,NULL,NULL,NULL,NULL,1,16,'en|1|16'),(13,'en',NULL,'Love and Deepspace bag charm, Love and Deepspace plush, Love and Deepspace keychain, Love and Deepspace merchandise UAE, Love and Deepspace gifts, plush bag charm UAE, kawaii bag charms Dubai, cute plush keychains UAE, anime bag charms UAE, character plush charm, Love and Deepspace accessories, kawaii accessories UAE, Kawaii Blessings',NULL,NULL,NULL,NULL,NULL,NULL,1,17,'en|1|17'),(14,'en',NULL,'Shop Love and Deepspace plush bag charms in the UAE. Cute collectible charms for handbags, backpacks, keys and gifts, available from Kawaii Blessings.',NULL,NULL,NULL,NULL,NULL,NULL,1,18,'en|1|18'),(15,NULL,NULL,NULL,NULL,NULL,65.0000,NULL,NULL,NULL,1,11,'1|11'),(16,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,12,'1|12'),(17,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,13,'1|13'),(18,NULL,'default',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,14,'default|1|14'),(19,NULL,'default',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,15,'default|1|15'),(20,NULL,'default',NULL,0,NULL,NULL,NULL,NULL,NULL,1,29,'default|1|29'),(21,NULL,'default',NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,30,'default|1|30'),(22,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,1,5,'1|5'),(23,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,1,6,'1|6'),(24,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,1,7,'1|7'),(25,NULL,'default',NULL,1,NULL,NULL,NULL,NULL,NULL,1,8,'default|1|8'),(26,NULL,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,1,26,'1|26'),(27,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,1,19,'1|19'),(28,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,1,20,'1|20'),(29,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,1,21,'1|21'),(30,NULL,NULL,'1',NULL,NULL,NULL,NULL,NULL,NULL,1,22,'1|22');
