INSERT INTO `theme_section_translations` VALUES (1,1,'en','{\"images\": [{\"link\": \"\", \"image\": \"storage/themes/default/sections/1/nCEwxu2z5bdCrwB6KSgAhAcsqaMaN2YXn3J10msi.webp\", \"title\": \"Get Ready For New Collection\"}, {\"link\": \"\", \"image\": \"storage/themes/default/sections/1/Tk4LQu1SqUVRsYWqIQUBuXVYefejoS4y3TKl88gS.webp\", \"title\": \"Get Ready For New Collection\"}, {\"link\": \"\", \"image\": \"storage/themes/default/sections/1/jZhSNc3edpHbVLvjXG0agbrVFMa7hy0xHIBh5so5.webp\", \"title\": \"Get Ready For New Collection\"}]}',NULL),(2,2,'en','{\"css\": \"/* =========================================================\\n   KAWAII BLESSINGS - ANNOUNCEMENT / OFFER SCROLLER\\n   PREMIUM GOLD ANIMATED FRAME\\n   ========================================================= */\\n\\n.kawaii-offer-bar {\\n    position: relative;\\n    width: 100%;\\n    overflow: hidden;\\n\\n    background:\\n        linear-gradient(\\n            90deg,\\n            #fff4f7 0%,\\n            #ffe6ee 35%,\\n            #fff0f5 65%,\\n            #ffe5ef 100%\\n        );\\n\\n    /*\\n       Thicker gold border\\n    */\\n    border: 3px solid #d6ad4f;\\n    box-sizing: border-box;\\n\\n    padding: 10px 0;\\n\\n    color: #55363f;\\n\\n    font-family: inherit;\\n\\n    /*\\n       Animated gold glow\\n    */\\n    box-shadow:\\n        inset 0 1px 0 rgba(255,255,255,0.95),\\n        inset 0 0 8px rgba(255,224,135,0.20),\\n        0 0 6px rgba(214,173,79,0.28),\\n        0 3px 15px rgba(184,137,40,0.16);\\n\\n    animation:\\n        kawaiiGoldGlow 3.2s ease-in-out infinite;\\n}\\n\\n\\n/* =========================================================\\n   GOLD BORDER GLOW ANIMATION\\n   ========================================================= */\\n\\n@keyframes kawaiiGoldGlow {\\n\\n    0% {\\n        border-color: #c99b35;\\n\\n        box-shadow:\\n            inset 0 1px 0 rgba(255,255,255,0.95),\\n            inset 0 0 7px rgba(255,224,135,0.15),\\n            0 0 4px rgba(201,155,53,0.20),\\n            0 3px 14px rgba(184,137,40,0.12);\\n    }\\n\\n    50% {\\n        border-color: #f0ce72;\\n\\n        box-shadow:\\n            inset 0 1px 0 rgba(255,255,255,1),\\n            inset 0 0 11px rgba(255,232,160,0.30),\\n            0 0 10px rgba(240,206,114,0.42),\\n            0 4px 18px rgba(184,137,40,0.20);\\n    }\\n\\n    100% {\\n        border-color: #c99b35;\\n\\n        box-shadow:\\n            inset 0 1px 0 rgba(255,255,255,0.95),\\n            inset 0 0 7px rgba(255,224,135,0.15),\\n            0 0 4px rgba(201,155,53,0.20),\\n            0 3px 14px rgba(184,137,40,0.12);\\n    }\\n\\n}\\n\\n\\n/* =========================================================\\n   EDGE FADE\\n   ========================================================= */\\n\\n.kawaii-offer-bar::before,\\n.kawaii-offer-bar::after {\\n    content: \\\"\\\";\\n    position: absolute;\\n\\n    top: 3px;\\n    bottom: 3px;\\n\\n    width: 75px;\\n\\n    z-index: 3;\\n\\n    pointer-events: none;\\n}\\n\\n\\n.kawaii-offer-bar::before {\\n    left: 3px;\\n\\n    background: linear-gradient(\\n        90deg,\\n        #fff2f6 0%,\\n        rgba(255,242,246,0) 100%\\n    );\\n}\\n\\n\\n.kawaii-offer-bar::after {\\n    right: 3px;\\n\\n    background: linear-gradient(\\n        270deg,\\n        #ffe9f0 0%,\\n        rgba(255,233,240,0) 100%\\n    );\\n}\\n\\n\\n/* =========================================================\\n   SCROLLING TRACK\\n   ========================================================= */\\n\\n.kawaii-offer-track {\\n    display: flex;\\n\\n    width: max-content;\\n\\n    animation:\\n        kawaiiTicker 34s linear infinite;\\n\\n    will-change: transform;\\n}\\n\\n\\n/* pause ticker when hovering */\\n.kawaii-offer-bar:hover .kawaii-offer-track {\\n    animation-play-state: paused;\\n}\\n\\n\\n/* stronger gold glow when hovering */\\n.kawaii-offer-bar:hover {\\n    border-color: #f1ce6e;\\n\\n    box-shadow:\\n        inset 0 1px 0 rgba(255,255,255,1),\\n        inset 0 0 12px rgba(255,229,147,0.30),\\n        0 0 14px rgba(224,184,83,0.45),\\n        0 5px 22px rgba(184,137,40,0.20);\\n}\\n\\n\\n/* =========================================================\\n   OFFER GROUP\\n   ========================================================= */\\n\\n.kawaii-offer-group {\\n    display: flex;\\n    align-items: center;\\n\\n    flex-shrink: 0;\\n\\n    gap: 34px;\\n\\n    padding-right: 34px;\\n}\\n\\n\\n/* =========================================================\\n   OFFER ITEM\\n   ========================================================= */\\n\\n.kawaii-offer-item {\\n    display: flex;\\n    align-items: center;\\n\\n    gap: 8px;\\n\\n    white-space: nowrap;\\n\\n    font-size: 15px;\\n    font-weight: 500;\\n\\n    letter-spacing: 0.01em;\\n\\n    line-height: 1.4;\\n}\\n\\n\\n/* =========================================================\\n   STRONG TEXT\\n   ========================================================= */\\n\\n.kawaii-offer-item strong {\\n    font-weight: 700;\\n\\n    color: #d94f7c;\\n}\\n\\n\\n/* =========================================================\\n   HIGHLIGHT TEXT\\n   ========================================================= */\\n\\n.offer-highlight {\\n    display: inline-block;\\n\\n    margin: 0 4px;\\n\\n    color: #ed5e8e;\\n\\n    font-weight: 700;\\n}\\n\\n\\n/* =========================================================\\n   KAOMOJI\\n   ========================================================= */\\n\\n.offer-kaomoji {\\n    margin: 0 4px;\\n\\n    color: #a36b91;\\n}\\n\\n\\n/* =========================================================\\n   FLOWER\\n   ========================================================= */\\n\\n.offer-flower {\\n    display: inline-block;\\n\\n    font-size: 16px;\\n\\n    animation:\\n        kawaiiFlowerFloat 2.8s ease-in-out infinite;\\n}\\n\\n\\n/* subtle flower movement */\\n@keyframes kawaiiFlowerFloat {\\n\\n    0%,\\n    100% {\\n        transform:\\n            translateY(0)\\n            rotate(0deg);\\n    }\\n\\n    50% {\\n        transform:\\n            translateY(-2px)\\n            rotate(8deg);\\n    }\\n\\n}\\n\\n\\n/* =========================================================\\n   HEART SEPARATOR\\n   ========================================================= */\\n\\n.kawaii-offer-divider {\\n    display: inline-flex;\\n    align-items: center;\\n    justify-content: center;\\n\\n    width: 28px;\\n    height: 28px;\\n\\n    border-radius: 50%;\\n\\n    background:\\n        linear-gradient(\\n            145deg,\\n            rgba(255,255,255,0.95),\\n            rgba(255,244,248,0.88)\\n        );\\n\\n    color: #ee7fa5;\\n\\n    font-size: 17px;\\n\\n    border: 2px solid rgba(214,173,79,0.58);\\n\\n    box-shadow:\\n        0 2px 8px rgba(184,137,40,0.12),\\n        inset 0 1px 0 rgba(255,255,255,1);\\n\\n    flex-shrink: 0;\\n\\n    animation:\\n        kawaiiHeartPulse 2.5s ease-in-out infinite;\\n}\\n\\n\\n/* =========================================================\\n   HEART ANIMATION\\n   ========================================================= */\\n\\n@keyframes kawaiiHeartPulse {\\n\\n    0%,\\n    100% {\\n        transform: scale(1);\\n\\n        border-color:\\n            rgba(214,173,79,0.50);\\n\\n        box-shadow:\\n            0 2px 8px rgba(184,137,40,0.10);\\n    }\\n\\n    50% {\\n        transform: scale(1.08);\\n\\n        border-color:\\n            rgba(241,207,112,0.90);\\n\\n        box-shadow:\\n            0 0 9px rgba(225,188,90,0.28);\\n    }\\n\\n}\\n\\n\\n/* =========================================================\\n   CONTINUOUS TICKER MOVEMENT\\n   ========================================================= */\\n\\n@keyframes kawaiiTicker {\\n\\n    from {\\n        transform: translateX(0);\\n    }\\n\\n    to {\\n        transform: translateX(-50%);\\n    }\\n\\n}\\n\\n\\n/* =========================================================\\n   TABLET\\n   ========================================================= */\\n\\n@media (max-width: 768px) {\\n\\n    .kawaii-offer-bar {\\n        padding: 8px 0;\\n\\n        border-width: 2px;\\n    }\\n\\n    .kawaii-offer-item {\\n        font-size: 13px;\\n    }\\n\\n    .kawaii-offer-group {\\n        gap: 25px;\\n\\n        padding-right: 25px;\\n    }\\n\\n    .kawaii-offer-divider {\\n        width: 24px;\\n        height: 24px;\\n\\n        font-size: 14px;\\n\\n        border-width: 1.5px;\\n    }\\n\\n    .kawaii-offer-track {\\n        animation-duration: 30s;\\n    }\\n\\n}\\n\\n\\n/* =========================================================\\n   MOBILE\\n   ========================================================= */\\n\\n@media (max-width: 525px) {\\n\\n    .kawaii-offer-bar {\\n        padding: 7px 0;\\n\\n        border-width: 2px;\\n    }\\n\\n    .kawaii-offer-item {\\n        font-size: 12px;\\n\\n        gap: 5px;\\n    }\\n\\n    .offer-highlight {\\n        margin: 0 2px;\\n    }\\n\\n    .kawaii-offer-group {\\n        gap: 20px;\\n\\n        padding-right: 20px;\\n    }\\n\\n    .kawaii-offer-divider {\\n        width: 22px;\\n        height: 22px;\\n\\n        font-size: 13px;\\n    }\\n\\n    .kawaii-offer-bar::before,\\n    .kawaii-offer-bar::after {\\n        width: 30px;\\n\\n        top: 2px;\\n        bottom: 2px;\\n    }\\n\\n    .kawaii-offer-bar::before {\\n        left: 2px;\\n    }\\n\\n    .kawaii-offer-bar::after {\\n        right: 2px;\\n    }\\n\\n    .kawaii-offer-track {\\n        animation-duration: 26s;\\n    }\\n\\n}\\n\\n\\n/* =========================================================\\n   ACCESSIBILITY\\n   ========================================================= */\\n\\n@media (prefers-reduced-motion: reduce) {\\n\\n    .kawaii-offer-track,\\n    .kawaii-offer-bar,\\n    .offer-flower,\\n    .kawaii-offer-divider {\\n        animation: none;\\n    }\\n\\n    .kawaii-offer-bar {\\n        overflow-x: auto;\\n    }\\n\\n}\", \"html\": \"<div class=\\\"kawaii-offer-bar\\\">\\n    <div class=\\\"kawaii-offer-track\\\">\\n\\n        <div class=\\\"kawaii-offer-group\\\">\\n            <div class=\\\"kawaii-offer-item\\\">\\n                <span class=\\\"offer-flower\\\">🌸</span>\\n                <span>\\n                    <strong>100% Authentic Products Guaranteed</strong>\\n                    <span class=\\\"offer-highlight\\\">or your money is back!!</span>\\n                    💰💕\\n                </span>\\n                <span class=\\\"offer-flower\\\">🌸</span>\\n            </div>\\n\\n            <span class=\\\"kawaii-offer-divider\\\">♡</span>\\n\\n            <div class=\\\"kawaii-offer-item\\\">\\n                <span>\\n                    Welcome to <strong>Kawaii Blessings</strong>, sweetie-pie!\\n                    <span class=\\\"offer-kaomoji\\\">(˶ᵔ ᵕ ᵔ˶)</span>\\n                    <span class=\\\"offer-highlight\\\">20% OFF + Free Shipping</span>\\n                    for orders of <strong>AED 299+</strong> in UAE 🇦🇪 only!!\\n                    ✧ﾟ･: *ヽ(◕ヮ◕ヽ)💖\\n                </span>\\n            </div>\\n\\n            <span class=\\\"kawaii-offer-divider\\\">♡</span>\\n        </div>\\n\\n\\n        \\n        <div class=\\\"kawaii-offer-group\\\">\\n            <div class=\\\"kawaii-offer-item\\\">\\n                <span class=\\\"offer-flower\\\">🌸</span>\\n                <span>\\n                    <strong>100% Authentic Products Guaranteed</strong>\\n                    <span class=\\\"offer-highlight\\\">or your money is back!!</span>\\n                    💰💕\\n                </span>\\n                <span class=\\\"offer-flower\\\">🌸</span>\\n            </div>\\n\\n            <span class=\\\"kawaii-offer-divider\\\">♡</span>\\n\\n            <div class=\\\"kawaii-offer-item\\\">\\n                <span>\\n                    Welcome to <strong>Kawaii Blessings</strong>, sweetie-pie!\\n                    <span class=\\\"offer-kaomoji\\\">(˶ᵔ ᵕ ᵔ˶)</span>\\n                    <span class=\\\"offer-highlight\\\">20% OFF + Free Shipping</span>\\n                    for orders of <strong>AED 299+</strong> in UAE 🇦🇪 only!!\\n                    ✧ﾟ･: *ヽ(◕ヮ◕ヽ)💖\\n                </span>\\n            </div>\\n\\n            <span class=\\\"kawaii-offer-divider\\\">♡</span>\\n        </div>\\n\\n    </div>\\n</div>\"}',NULL),(3,5,'en','{\"css\": \".top-collection-container {overflow: hidden;}.top-collection-header {padding-left: 15px;padding-right: 15px;text-align: center;font-size: 70px;line-height: 90px;color: #060C3B;margin-top: 80px;}.top-collection-header h2 {max-width: 595px;margin-left: auto;margin-right: auto;font-family: DM Serif Display;}.top-collection-grid {display: flex;flex-wrap: wrap;gap: 32px;justify-content: center;margin-top: 60px;width: 100%;margin-right: auto;margin-left: auto;padding-right: 90px;padding-left: 90px;}.top-collection-card {position: relative;background: #f9fafb;overflow:hidden;border-radius:20px;}.top-collection-card img {border-radius: 16px;max-width: 100%;text-indent:-9999px;transition: transform 300ms ease;transform: scale(1);}.top-collection-card:hover img {transform: scale(1.05);transition: all 300ms ease;}.top-collection-card h3 {color: #060C3B;font-size: 30px;font-family: DM Serif Display;transform: translateX(-50%);width: max-content;left: 50%;bottom: 30px;position: absolute;margin: 0;font-weight: inherit;}@media not all and (min-width: 525px) {.top-collection-header {margin-top: 28px;font-size: 20px;line-height: 1.5;}.top-collection-grid {gap: 10px}}@media not all and (min-width: 768px) {.top-collection-header {margin-top: 30px;font-size: 28px;line-height: 3;}.top-collection-header h2 {line-height:2; margin-bottom:20px;} .top-collection-grid {gap: 14px}} @media not all and (min-width: 1024px) {.top-collection-grid {padding-left: 30px;padding-right: 30px;}}@media (max-width: 768px) {.top-collection-grid { row-gap:15px; column-gap:0px;justify-content: space-between;margin-top: 0px;} .top-collection-card{width:48%} .top-collection-card img {width:100%;} .top-collection-card h3 {font-size:24px; bottom: 16px;}}@media (max-width:520px) { .top-collection-grid{padding-left: 15px;padding-right: 15px;} .top-collection-card h3 {font-size:18px; bottom: 10px;}}\", \"html\": \"<div class=\\\"top-collection-container\\\">\\n                                <div class=\\\"top-collection-header\\\">\\n                                    <h2>The game with our new additions!</h2>\\n                                </div>\\n\\n                                <div class=\\\"top-collection-grid container\\\">\\n                                    <div class=\\\"top-collection-card\\\">\\n                                        <a href=\\\"#electronics\\\" aria-label=\\\"The game with our new additions!\\\">\\n                                            <img src=\\\"\\\" data-src=\\\"storage/themes/default/sections/8/w05R36lGTJtGu0t3EEFNvDmVw8lL9ZLVe8afGDlZ.webp\\\" class=\\\"lazy\\\" width=\\\"396\\\" height=\\\"396\\\" alt=\\\"The game with our new additions!\\\">\\n                                        </a>\\n                                    </div>\\n\\n                                    <div class=\\\"top-collection-card\\\">\\n                                        <a href=\\\"#mens\\\" aria-label=\\\"The game with our new additions!\\\">\\n                                            <img src=\\\"\\\" data-src=\\\"storage/themes/default/sections/8/C5NknaZARgheEv0XAbTkdxoIgkpNrCzooGM5CJ2J.webp\\\" class=\\\"lazy\\\" width=\\\"396\\\" height=\\\"396\\\" alt=\\\"The game with our new additions!\\\">\\n                                        </a>\\n                                    </div>\\n\\n                                    <div class=\\\"top-collection-card\\\">\\n                                        <a href=\\\"#womens\\\" aria-label=\\\"The game with our new additions!\\\">\\n                                            <img src=\\\"\\\" data-src=\\\"storage/themes/default/sections/8/wxwJaXhHv05kPLmRVHuNqCcjzrCTcTuY6IyzJbHP.webp\\\" class=\\\"lazy\\\" width=\\\"396\\\" height=\\\"396\\\" alt=\\\"The game with our new additions!\\\">\\n                                        </a>\\n                                    </div>\\n\\n                                    <div class=\\\"top-collection-card\\\">\\n                                        <a href=\\\"#formal-wear-men\\\" aria-label=\\\"The game with our new additions!\\\">\\n                                            <img src=\\\"\\\" data-src=\\\"storage/themes/default/sections/8/C9W5bS5lfX3MtHkxSBXkn0xvccReB5qkvdtEZF04.webp\\\" class=\\\"lazy\\\" width=\\\"396\\\" height=\\\"396\\\" alt=\\\"The game with our new additions!\\\">\\n                                        </a>\\n                                    </div>\\n\\n                                    <div class=\\\"top-collection-card\\\">\\n                                        <a href=\\\"#formal-wear-female\\\" aria-label=\\\"The game with our new additions!\\\">\\n                                            <img src=\\\"\\\" data-src=\\\"storage/themes/default/sections/8/NxzWwBp5FbHaIvKXKIfNeEx6qvUwi8X6MCbnzjaZ.webp\\\" class=\\\"lazy\\\" width=\\\"396\\\" height=\\\"396\\\" alt=\\\"The game with our new additions!\\\">\\n                                        </a>\\n                                    </div>\\n\\n                                    <div class=\\\"top-collection-card\\\">\\n                                        <a href=\\\"#wellness\\\" aria-label=\\\"The game with our new additions!\\\">\\n                                            <img src=\\\"\\\" data-src=\\\"storage/themes/default/sections/8/HXpN5kfGDPmkYTV51Nd8qpIkUon2dkyrxdUah42e.webp\\\" class=\\\"lazy\\\" width=\\\"396\\\" height=\\\"396\\\" alt=\\\"The game with our new additions!\\\">\\n                                        </a>\\n                                    </div>\\n                         