t: -40%;\\n\\n    width: 23%;\\n    height: 220%;\\n\\n    background:\\n        linear-gradient(\\n            90deg,\\n            transparent,\\n            rgba(255,255,255,.95),\\n            transparent\\n        );\\n\\n    transform: rotate(18deg);\\n\\n    transition:\\n        left .58s ease;\\n}\\n\\n\\n#kb-new-section .all:hover {\\n    transform:\\n        translateY(-2px);\\n\\n    color: #ca4877;\\n\\n    border-color:\\n        rgba(208,160,78,.75);\\n\\n    box-shadow:\\n        0 9px 20px\\n        rgba(218,111,147,.12);\\n}\\n\\n\\n#kb-new-section .all:hover::before {\\n    left: 125%;\\n}\\n\\n\\n#kb-new-section .all-arrow {\\n    display: inline-block;\\n\\n    transition:\\n        transform .25s ease;\\n}\\n\\n\\n#kb-new-section .all:hover .all-arrow {\\n    transform:\\n        translateX(4px);\\n}\\n\\n\\n/* =========================================================\\n   CAROUSEL AREA\\n   ========================================================= */\\n\\n#kb-new-section .wrap {\\n    position: relative;\\n\\n    padding:\\n        2px 0 4px;\\n}\\n\\n\\n/* subtle fade edges */\\n\\n#kb-new-section .wrap::before,\\n#kb-new-section .wrap::after {\\n    content: \\\"\\\";\\n\\n    position: absolute;\\n\\n    z-index: 3;\\n\\n    top: 0;\\n    bottom: 0;\\n\\n    width: 16px;\\n\\n    pointer-events: none;\\n}\\n\\n\\n#kb-new-section .wrap::before {\\n    left: 0;\\n\\n    background:\\n        linear-gradient(\\n            90deg,\\n            #fff7f8,\\n            transparent\\n        );\\n}\\n\\n\\n#kb-new-section .wrap::after {\\n    right: 0;\\n\\n    background:\\n        linear-gradient(\\n            270deg,\\n            #fff7f8,\\n            transparent\\n        );\\n}\\n\\n\\n/* =========================================================\\n   TRACK\\n   ========================================================= */\\n\\n#kb-new-section .track {\\n    position: relative;\\n\\n    z-index: 2;\\n\\n    display: grid;\\n\\n    grid-auto-flow: column;\\n\\n    grid-auto-columns:\\n        calc(20% - 10px);\\n\\n    gap: 12px;\\n\\n    overflow-x: auto;\\n    overflow-y: hidden;\\n\\n    padding:\\n        5px 2px 12px;\\n\\n    scroll-behavior: smooth;\\n\\n    scroll-snap-type:\\n        x proximity;\\n\\n    scrollbar-width: none;\\n\\n    overscroll-behavior-inline:\\n        contain;\\n}\\n\\n\\n#kb-new-section .track::-webkit-scrollbar {\\n    display: none;\\n}\\n\\n\\n/* =========================================================\\n   PRODUCT CARD\\n   ========================================================= */\\n\\n#kb-new-section .product {\\n    --kb-rx: 0deg;\\n    --kb-ry: 0deg;\\n    --kb-lift: 0px;\\n\\n    position: relative;\\n\\n    overflow: hidden;\\n\\n    scroll-snap-align: start;\\n\\n    border:\\n        1px solid\\n        rgba(234,207,213,.96);\\n\\n    border-radius: 14px;\\n\\n    background:\\n        rgba(255,255,255,.94);\\n\\n    box-shadow:\\n        0 6px 16px\\n        rgba(177,106,124,.055);\\n\\n    transform:\\n        perspective(900px)\\n        translateY(var(--kb-lift))\\n        rotateX(var(--kb-rx))\\n        rotateY(var(--kb-ry));\\n\\n    transform-style:\\n        preserve-3d;\\n\\n    transition:\\n        transform .20s ease,\\n        border-color .28s ease,\\n        box-shadow .28s ease;\\n\\n    animation:\\n        kbNewCardEntrance\\n        .62s\\n        cubic-bezier(.2,.8,.2,1)\\n        both;\\n\\n    will-change: transform;\\n}\\n\\n\\n/* fine gold inner border */\\n\\n#kb-new-section .product::before {\\n    content: \\\"\\\";\\n\\n    position: absolute;\\n\\n    z-index: 7;\\n\\n    inset: 4px;\\n\\n    pointer-events: none;\\n\\n    border:\\n        1px solid transparent;\\n\\n    border-radius: 10px;\\n\\n    transition:\\n        border-color .3s ease,\\n        box-shadow .3s ease;\\n}\\n\\n\\n/* shine passing over card */\\n\\n#kb-new-section .product::after {\\n    content: \\\"\\\";\\n\\n    position: absolute;\\n\\n    z-index: 6;\\n\\n    top: -55%;\\n    left: -55%;\\n\\n    width: 29%;\\n    height: 210%;\\n\\n    pointer-events: none;\\n\\n    opacity: 0;\\n\\n    background:\\n        linear-gradient(\\n            90deg,\\n            transparent,\\n            rgba(255,255,255,.80),\\n            transparent\\n        );\\n\\n    transform: rotate(18deg);\\n\\n    transition:\\n        left .70s ease,\\n        opacity .24s ease;\\n}\\n\\n\\n/* product hover */\\n\\n#kb-new-section .product:hover {\\n    --kb-lift: -7px;\\n\\n    border-color:\\n        rgba(210,164,80,.80);\\n\\n    box-shadow:\\n        0 17px 32px\\n        rgba(169,100,115,.14);\\n}\\n\\n\\n#kb-new-section .product:hover::before {\\n    border-color:\\n        rgba(220,176,90,.38);\\n\\n    box-shadow:\\n        0 0 15px\\n        rgba(221,174,81,.08)\\n        inset;\\n}\\n\\n\\n#kb-new-section .product:hover::after {\\n    left: 130%;\\n\\n    opacity: 1;\\n}\\n\\n\\n/* =========================================================\\n   MEDIA\\n   ========================================================= */\\n\\n#kb-new-section .media {\\n    position: relative;\\n\\n    overflow: hidden;\\n\\n    aspect-ratio:\\n        1.16 / 1;\\n\\n    margin:\\n        7px 7px 0;\\n\\n    border-radius: 10px;\\n\\n    background:\\n        radial-gradient(\\n            circle at 50% 35%,\\n            rgba(255,255,255,.97),\\n            transparent 42%\\n        ),\\n        linear-gradient(\\n            145deg,\\n            #fff0f4,\\n            #fff8fa\\n        );\\n\\n    transform:\\n        translateZ(8px);\\n}\\n\\n\\n#kb-new-section .media a {\\n    display: block;\\n\\n    width: 100%;\\n    height: 100%;\\n}\\n\\n\\n#kb-new-section .media img {\\n    display: block;\\n\\n    width: 100%;\\n    height: 100%;\\n\\n    object-fit: cover;\\n\\n    object-position: center;\\n\\n    transform:\\n        scale(1.002);\\n\\n    transition:\\n        transform .62s\\n        cubic-bezier(.16,.8,.25,1),\\n        filter .45s ease;\\n}\\n\\n\\n#kb-new-section .product:hover .media img {\\n    transform:\\n        scale(1.07);\\n\\n    filter:\\n        saturate(1.045)\\n        brightness(1.012);\\n}\\n\\n\\n/* soft image overlay */\\n\\n#kb-new-section .media::after {\\n    content: \\\"\\\";\\n\\n    position: absolute;\\n\\n    inset: 0;\\n\\n    pointer-events: none;\\n\\n    background:\\n        linear-gradient(\\n            180deg,\\n            transparent 64%,\\n            rgba(255,238,244,.10)\\n        );\\n}\\n\\n\\n/* =========================================================\\n   NO IMAGE PLACEHOLDER\\n   ========================================================= */\\n\\n#kb-new-section .placeholder {\\n    width: 100%;\\n    height: 100%;\\n\\n    display: flex;\\n\\n    flex-direction: column;\\n\\n    align-items: center;\\n    justify-content: center;\\n\\n    gap: 8px;\\n\\n    color: #e594af;\\n\\n    background:\\n        radial-gradient(\\n            circle,\\n            #fff 0%,\\n            #fff3f7 68%,\\n            #ffeaf2 100%\\n        );\\n}\\n\\n\\n#kb-new-section .placeholder .ph-heart {\\n    font-size: 32px;\\n\\n    animation:\\n        kbNewHeartBeat\\n        2.5s ease-in-out infinite;\\n}\\n\\n\\n#kb-new-section .placeholder span:last-child {\\n    font-size: 10px;\\n\\n    font-weight: 800;\\n\\n    color: #a9818d;\\n}\\n\\n\\n/* =========================================================\\n   NEW / SALE BADGE\\n   ========================================================= */\\n\\n#kb-new-section .badge {\\n    position: absolute;\\n\\n    z-index: 5;\\n\\n    left: 8px;\\n    top: 8px;\\n\\n    min-height: 24px;\\n\\n    padding:\\n        0 9px;\\n\\n    display: inline-flex;\\n\\n    align-items: center;\\n    justify-content: center;\\n\\n    border:\\n        1px solid\\n        rgba(255,255,255,.65);\\n\\n    border-radius: 999px;\\n\\n    background:\\n        linear-gradient(\\n            180deg,\\n            #f891b2 0%,\\n            #e96592 100%\\n        );\\n\\n    color: #fff;\\n\\n    font-size: 9px;\\n\\n    line-height: 1;\\n\\n    font-weight: 900;\\n\\n    text-transform: uppercase;\\n\\n    letter-spacing: .025em;\\n\\n    box-shadow:\\n        0 5px 12px\\n        rgba(234,99,143,.19);\\n\\n    transition:\\n        transform .3s ease,\\n        box-shadow .3s ease;\\n}\\n\\n\\n#kb-new-section .badge.sale {\\n    background:\\n        linear-gradient(\\n            180deg,\\n            #dfb05f,\\n            #bd8730\\n        );\\n\\n    box-shadow:\\n        0 5px 12px\\n        rgba(189,135,48,.19);\\n}\\n\\n\\n#kb-new-section .product:hover .badge {\\n    transform:\\n        translateY(-2px)\\n        scale(1.06);\\n\\n    box-shadow:\\n        0 7px 16px\\n        rgba(234,99,143,.23);\\n}\\n\\n\\n/* =========================================================\\n   PRODUCT INFO\\n   ========================================================= */\\n\\n#kb-new-section .info {\\n    position: relative;\\n\\n    z-index: 3;\\n\\n    padding:\\n        10px 11px 12px;\\n\\n    transform:\\n        translateZ(5px);\\n}\\n\\n\\n#kb-new-section .name {\\n    min-height: 35px;\\n\\n    overflow: hidden;\\n\\n    display: -webkit-box;\\n\\n    -webkit-box-orient:\\n        vertical;\\n\\n    -webkit-line-clamp: 2;\\n\\n    color:\\n        #55363e;\\n\\n    font-size: 11.5px;\\n\\n    font-weight: 700;\\n\\n    line-height: 1.43;\\n\\n    transition:\\n        color .25s ease;\\n}\\n\\n\\n#kb-new-section .product:hover .name {\\n    color:\\n        #9b6921;\\n}\\n\\n\\n/* =========================================================\\n   PRICE + WISHLIST\\n   ========================================================= */\\n\\n#kb-new-section .bottom {\\n    margin-top: 7px;\\n\\n    display: flex;\\n\\n    align-items: center;\\n    justify-content: space-between;\\n\\n    gap: 8px;\\n}\\n\\n\\n#kb-new-section .price {\\n    min-width: 0;\\n\\n    color:\\n        #493036;\\n\\n    font-size: 11.5px;\\n\\n    font-weight: 900;\\n\\n    white-space: nowrap;\\n}\\n\\n\\n/* Bagisto price HTML */\\n\\n#kb-new-section .price * {\\n    font-size: inherit;\\n\\n    line-height: 1.3;\\n}\\n\\n\\n#kb-new-section .price .price-label {\\n    display: none !important;\\n}\\n\\n\\n#kb-new-section .price .regular-price,\\n#kb-new-section .price .final-price,\\n#kb-new-section .price .special-price {\\n    color:\\n        #493036;\\n}\\n\\n\\n#kb-new-section .price del,\\n#kb-new-section .price .old-price {\\n    margin-left: 4px;\\n\\n    color:\\n        #aa8c95;\\n\\n    font-size: 9px;\\n}\\n\\n\\n/* heart */\\n\\n#kb-new-section .heart {\\n    position: relative;\\n\\n    overflow: hidden;\\n\\n    flex: 0 0 auto;\\n\\n    width: 30px;\\n    height: 30px;\\n\\n    display: flex;\\n\\n    align-items: center;\\n    justify-content: center;\\n\\n    border:\\n        1px solid\\n        #ecc7d3;\\n\\n    border-radius: 50%;\\n\\n    background: #fff;\\n\\n    color:\\n        #ea779d;\\n\\n    font-size: 17px;\\n\\n    line-height: 1;\\n\\n    box-shadow:\\n        0 4px 10px\\n        rgba(215,108,145,.06);\\n\\n    transition:\\n        transform .25s ease,\\n        background .25s ease,\\n        color .25s ease,\\n        border-color .25s ease,\\n        box-shadow .25s ease;\\n}\\n\\n\\n#kb-new-section .heart:hover {\\n    transform:\\n        scale(1.12)\\n        rotate(-6deg);\\n\\n    color: #fff;\\n\\n    background:\\n        linear-gradient(\\n            145deg,\\n            #f898b6,\\n            #ea668f\\n        );\\n\\n    border-color:\\n        transparent;\\n\\n    box-shadow:\\n        0 7px 15px\\n        rgba(226,91,137,.20);\\n}\\n\\n\\n/* =========================================================\\n   CAROUSEL ARROWS\\n   ========================================================= */\\n\\n#kb-new-section .arrow {\\n    position: absolute;\\n\\n    z-index: 10;\\n\\n    top: 45%;\\n\\n    width: 42px;\\n    height: 42px;\\n\\n    display: flex;\\n\\n    align-items: center;\\n    justify-content: center;\\n\\n    padding: 0;\\n\\n    border:\\n        1px solid\\n        rgba(220,174,91,.60);\\n\\n    border-radius: 50%;\\n\\n    background:\\n        rgba(255,255,255,.97);\\n\\n    color:\\n        #cd6287;\\n\\n    box-shadow:\\n        0 9px 22px\\n        rgba(168,105,122,.12);\\n\\n    font-family:\\n        Georgia,\\n        serif;\\n\\n    font-size: 25px;\\n\\n    line-height: 1;\\n\\n    cursor: pointer;\\n\\n    transform:\\n        translateY(-50%);\\n\\n    transition:\\n        transform .25s ease,\\n        color .25s ease,\\n        background .25s ease,\\n        box-shadow .25s ease,\\n        border-color .25s ease;\\n\\n    animation:\\n        kbNewArrowFloat\\n        4s ease-in-out infinite;\\n}\\n\\n\\n#kb-new-section .arrow:hover {\\n    color: #fff;\\n\\n    background:\\n        linear-gradient(\\n            145deg,\\n            #f694b4,\\n            #df628c\\n        );\\n\\n    border-color:\\n        rgba(255,255,255,.85);\\n\\n    box-shadow:\\n        0 12px 26px\\n        rgba(220,91,137,.22);\\n}\\n\\n\\n#kb-new-section .left {\\n    left: -20px;\\n}\\n\\n\\n#kb-new-section .right {\\n    right: -20px;\\n\\n    animation-delay: -2s;\\n}\\n\\n\\n#kb-new-section .left:hover {\\n    transform:\\n        translateY(-50%)\\n        translateX(-3px)\\n        scale(1.07);\\n}\\n\\n\\n#kb-new-section .right:hover {\\n    transform:\\n        translateY(-50%)\\n        translateX(3px)\\n        scale(1.07);\\n}\\n\\n\\n/* =========================================================\\n   LOADING / ERROR\\n   ========================================================= */\\n\\n#kb-new-section .msg {\\n    min-width: 100%;\\n\\n    padding: 28px;\\n\\n    border:\\n        1px dashed\\n        #e8c3cf;\\n\\n    border-radius: 12px;\\n\\n    background:\\n        rgba(255,255,255,.70);\\n\\n    color:\\n        var(--kb-muted);\\n\\n    font-size: 12px;\\n\\n    text-align: center;\\n}\\n\\n\\n/* =========================================================\\n   STAGGER PRODUCT ENTRANCE\\n   ========================================================= */\\n\\n#kb-new-section .product:nth-child(1) {\\n    animation-delay: .02s;\\n}\\n\\n#kb-new-section .product:nth-child(2) {\\n    animation-delay: .07s;\\n}\\n\\n#kb-new-section .product:nth-child(3) {\\n    animation-delay: .12s;\\n}\\n\\n#kb-new-section .product:nth-child(4) {\\n    animation-delay: .17s;\\n}\\n\\n#kb-new-section .product:nth-child(5) {\\n    animation-delay: .22s;\\n}\\n\\n#kb-new-section .product:nth-child(6) {\\n    animation-delay: .27s;\\n}\\n\\n#kb-new-section .product:nth-child(7) {\\n    animation-delay: .32s;\\n}\\n\\n#kb-new-section .product:nth-child(8) {\\n    animation-delay: .37s;\\n}\\n\\n#kb-new-section .product:nth-child(9) {\\n    animation-delay: .42s;\\n}\\n\\n#kb-new-section .product:nth-child(10) {\\n    animation-delay: .47s;\\n}\\n\\n#kb-new-section .product:nth-child(11) {\\n    animation-delay: .52s;\\n}\\n\\n#kb-new-section .product:nth-child(12) {\\n    animation-delay: .57s;\\n}\\n\\n\\n/* =========================================================\\n   KEYFRAMES\\n   ========================================================= */\\n\\n@keyframes kbNewCardEntrance {\\n\\n    from {\\n        opacity: 0;\\n\\n        transform:\\n            perspective(900px)\\n            translateY(18px)\\n            scale(.975);\\n    }\\n\\n    to {\\n        opacity: 1;\\n\\n        transform:\\n            perspective(900px)\\n            translateY(0)\\n            scale(1);\\n    }\\n}\\n\\n\\n@keyframes kbNewBowFloat {\\n\\n    0%,\\n    100% {\\n        transform:\\n            translateY(0)\\n            rotate(0deg);\\n    }\\n\\n    50% {\\n        transform:\\n            translateY(-4px)\\n            rotate(-2deg);\\n    }\\n}\\n\\n\\n@keyframes kbNewHeartBeat {\\n\\n    0%,\\n    100% {\\n        transform:\\n            scale(1);\\n    }\\n\\n    42% {\\n        transform:\\n            scale(1.17);\\n    }\\n\\n    60% {\\n        transform:\\n            scale(.97);\\n    }\\n\\n    72% {\\n        transform:\\n            scale(1.08);\\n    }\\n}\\n\\n\\n@keyframes kbNewSparkle {\\n\\n    0%,\\n    100% {\\n        opacity: .5;\\n\\n        transform:\\n            translateY(-7px)\\n            scale(.78)\\n            rotate(0);\\n    }\\n\\n    50% {\\n        opacity: 1;\\n\\n        transform:\\n            translateY(-9px)\\n            scale(1.2)\\n            rotate(14deg);\\n    }\\n}\\n\\n\\n@keyframes kbNewAmbientFloat {\\n\\n    0%,\\n    100% {\\n        opacity: .42;\\n\\n        transform:\\n            translateY(0)\\n            rotate(-4deg);\\n    }\\n\\n    50% {\\n        opacity: .82;\\n\\n        transform:\\n            translateY(-9px)\\n            rotate(5deg);\\n    }\\n}\\n\\n\\n@keyframes kbNewSectionSweep {\\n\\n    0%,\\n    65% {\\n        left: -35%;\\n\\n        opacity: 0;\\n    }\\n\\n    73% {\\n        opacity: .35;\\n    }\\n\\n    83% {\\n        left: 120%;\\n\\n        opacity: 0;\\n    }\\n\\n    100% {\\n        left: 120%;\\n\\n        opacity: 0;\\n    }\\n}\\n\\n\\n@keyframes kbNewArrowFloat {\\n\\n    0%,\\n    100% {\\n        margin-top: 0;\\n    }\\n\\n    50% {\\n        margin-top: -4px;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   TABLET\\n   ========================================================= */\\n\\n@media (max-width: 1050px) {\\n\\n    #kb-new-section .track {\\n        grid-auto-columns:\\n            calc(25% - 9px);\\n    }\\n}\\n\\n\\n/* =========================================================\\n   SMALL TABLET\\n   ========================================================= */\\n\\n@media (max-width: 780px) {\\n\\n    #kb-new-section {\\n        width:\\n            calc(100% - 18px);\\n\\n        padding:\\n            19px 12px 22px;\\n    }\\n\\n    #kb-new-section .track {\\n        grid-auto-columns:\\n            calc(33.333% - 8px);\\n    }\\n\\n    #kb-new-section .arrow {\\n        display: none;\\n    }\\n\\n    #kb-new-section .wrap::before,\\n    #kb-new-section .wrap::after {\\n        width: 8px;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   MOBILE\\n   ========================================================= */\\n\\n@media (max-width: 520px) {\\n\\n    #kb-new-section .head {\\n        align-items:\\n            flex-start;\\n\\n        flex-direction:\\n            column;\\n\\n        gap: 13px;\\n    }\\n\\n    #kb-new-section .heading-side {\\n        width: 100%;\\n    }\\n\\n    #kb-new-section .kb-new-bow {\\n        width: 43px;\\n        height: 32px;\\n\\n        margin-right: 8px;\\n    }\\n\\n    #kb-new-section h2 {\\n        font-size: 28px;\\n    }\\n\\n    #kb-new-section .sub {\\n        font-size: 11px;\\n    }\\n\\n    #kb-new-section .all {\\n        align-self: flex-end;\\n    }\\n\\n    #kb-new-section .track {\\n        grid-auto-columns:\\n            72%;\\n\\n        gap: 10px;\\n\\n        padding-bottom: 10px;\\n    }\\n\\n    #kb-new-section .name {\\n        font-size: 11px;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   VERY SMALL MOBILE\\n   ========================================================= */\\n\\n@media (max-width: 380px) {\\n\\n    #kb-new-section {\\n        width:\\n            calc(100% - 12px);\\n\\n        padding-inline:\\n            8px;\\n    }\\n\\n    #kb-new-section .track {\\n        grid-auto-columns:\\n            80%;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   REDUCED MOTION\\n   ========================================================= */\\n\\n@media (prefers-reduced-motion: reduce) {\\n\\n    #kb-new-section *,\\n    #kb-new-section *::before,\\n    #kb-new-section *::after {\\n        animation: none !important;\\n\\n        transition-duration:\\n            .01ms !important;\\n    }\\n\\n    #kb-new-section .product {\\n        transform: none !important;\\n    }\\n}\\n</style>\\n</head>\\n\\n\\n<body>\\n\\n<section id=\\\"kb-new-section\\\">\\n\\n    <!-- ambient kawaii details -->\\n\\n    <div\\n        class=\\\"kb-new-ambient\\\"\\n        aria-hidden=\\\"true\\\"\\n    >\\n        <span class=\\\"a1\\\">✦</span>\\n        <span class=\\\"a2\\\">✧</span>\\n        <span class=\\\"a3\\\">♡</span>\\n        <span class=\\\"a4\\\">✦</span>\\n        <span class=\\\"a5\\\">♡</span>\\n    </div>\\n\\n\\n    <div class=\\\"inner\\\">\\n\\n        <!-- =================================================\\n             HEADER\\n             ================================================= -->\\n\\n        <div class=\\\"head\\\">\\n\\n            <div class=\\\"heading-side\\\">\\n\\n                <!-- animated bow -->\\n\\n                <svg\\n                    class=\\\"kb-new-bow\\\"\\n                    viewBox=\\\"0 0 64 42\\\"\\n                    aria-hidden=\\\"true\\\"\\n                >\\n                    <defs>\\n\\n                        <linearGradient\\n                            id=\\\"kbNewBowGradient\\\"\\n                            x1=\\\"0\\\"\\n                            x2=\\\"1\\\"\\n                            y1=\\\"0\\\"\\n                            y2=\\\"1\\\"\\n                        >\\n                            <stop\\n                                offset=\\\"0%\\\"\\n                                stop-color=\\\"#ffd6e2\\\"\\n                            />\\n\\n                            <stop\\n                                offset=\\\"100%\\\"\\n                                stop-color=\\\"#f397b2\\\"\\n                            />\\n                        </linearGradient>\\n\\n                    </defs>\\n\\n\\n                    <g\\n                        fill=\\\"url(#kbNewBowGradient)\\\"\\n                        stroke=\\\"#e889a8\\\"\\n                        stroke-width=\\\"1.5\\\"\\n                        stroke-linejoin=\\\"round\\\"\\n                    >\\n\\n                        <path\\n                            d=\\\"\\n                                M31 18\\n                                C22 7 9 4 7 12\\n                                C5 20 16 24 29 21\\n                                Z\\n                            \\\"\\n                        />\\n\\n\\n                        <path\\n                            d=\\\"\\n                                M33 18\\n                                C42 7 55 4 57 12\\n                                C59 20 48 24 35 21\\n                                Z\\n                            \\\"\\n                        />\\n\\n\\n                        <rect\\n                            x=\\\"28.5\\\"\\n                            y=\\\"15\\\"\\n                            width=\\\"7\\\"\\n                            height=\\\"12\\\"\\n                            rx=\\\"3.5\\\"\\n                        />\\n\\n\\n                        <path\\n                            d=\\\"\\n                                M29 24\\n                                L20 36\\n                                L31 30\\n                                Z\\n                            \\\"\\n                        />\\n\\n\\n                        <path\\n                            d=\\\"\\n                                M35 24\\n                                L44 36\\n                                L33 30\\n                                Z\\n                            \\\"\\n                        />\\n\\n                    </g>\\n\\n                </svg>\\n\\n\\n                <div class=\\\"heading-copy\\\">\\n\\n                    <h2>\\n\\n                        Just Landed\\n\\n                        <span\\n                            class=\\\"title-heart\\\"\\n                            aria-hidden=\\\"true\\\"\\n                        >\\n                            ♡\\n                        </span>\\n\\n                        <span\\n                            class=\\\"heading-sparkles\\\"\\n                            aria-hidden=\\\"true\\\"\\n                        >\\n                            ✦ ✧\\n                        </span>\\n\\n                    </h2>\\n\\n\\n                    <p class=\\\"sub\\\">\\n                        Fresh finds you\'ll fall in love with\\n                    </p>\\n\\n                </div>\\n\\n            </div>\\n\\n\\n            <a\\n                class=\\\"all\\\"\\n                href=\\\"/search?sort=created_at-desc\\\"\\n            >\\n\\n                View all new arrivals\\n\\n                <span\\n                    class=\\\"all-arrow\\\"\\n                    aria-hidden=\\\"true\\\"\\n                >\\n                    →\\n                </span>\\n\\n            </a>\\n\\n        </div>\\n\\n\\n        <!-- =================================================\\n             CAROUSEL\\n             ================================================= -->\\n\\n        <div class=\\\"wrap\\\">\\n\\n            <button\\n                class=\\\"arrow left\\\"\\n                type=\\\"button\\\"\\n                aria-label=\\\"Previous products\\\"\\n            >\\n                ‹\\n            </button>\\n\\n\\n            <div\\n                id=\\\"kb-new-track\\\"\\n                class=\\\"track\\\"\\n            >\\n\\n                <div class=\\\"msg\\\">\\n                    Loading our newest kawaii treasures… ♡\\n                </div>\\n\\n            </div>\\n\\n\\n            <button\\n                class=\\\"arrow right\\\"\\n                type=\\\"button\\\"\\n                aria-label=\\\"Next products\\\"\\n            >\\n                ›\\n            </button>\\n\\n        </div>\\n\\n    </div>\\n\\n</section>\\n\\n\\n<script>\\n(function () {\\n\\n    \\\"use strict\\\";\\n\\n\\n    const section =\\n        document.getElementById(\\n            \\\"kb-new-section\\\"\\n        );\\n\\n\\n    const track =\\n        document.getElementById(\\n            \\\"kb-new-track\\\"\\n        );\\n\\n\\n    const leftButton =\\n        section.querySelector(\\n            \\\".arrow.left\\\"\\n        );\\n\\n\\n    const rightButton =\\n        section.querySelector(\\n            \\\".arrow.right\\\"\\n        );\\n\\n\\n    /*\\n     * Escape data returned from Bagisto\\n     * before inserting text/attributes.\\n     */\\n\\n    const escapeHTML = (value) => {\\n\\n        return String(value ?? \\\"\\\")\\n\\n            .replace(/&/g, \\\"&amp;\\\")\\n\\n            .replace(/</g, \\\"&lt;\\\")\\n\\n            .replace(/>/g, \\\"&gt;\\\")\\n\\n            .replace(/\\\"/g, \\\"&quot;\\\")\\n\\n            .replace(/\'/g, \\\"&#039;\\\");\\n    };\\n\\n\\n    /*\\n     * Build product URL.\\n     */\\n\\n    const productURL = (value) => {\\n\\n        value =\\n            String(value || \\\"\\\")\\n            .trim();\\n\\n\\n        if (!value) {\\n            return \\\"#\\\";\\n        }\\n\\n\\n        if (\\n            /^https?:\\\\/\\\\//i.test(value)\\n        ) {\\n            return value;\\n        }\\n\\n\\n        return value.startsWith(\\\"/\\\")\\n            ? value\\n            : \\\"/\\\" + value;\\n    };\\n\\n\\n    /*\\n     * Find best Bagisto image variant.\\n     */\\n\\n    const productImage = (product) => {\\n\\n        return (\\n\\n            product?.base_image\\n                ?.large_image_url ||\\n\\n            product?.base_image\\n                ?.medium_image_url ||\\n\\n            product?.base_image\\n                ?.small_image_url ||\\n\\n            product?.base_image\\n                ?.original_image_url ||\\n\\n            \\\"\\\"\\n\\n        );\\n    };\\n\\n\\n    /*\\n     * Enable subtle mouse tilt.\\n     *\\n     * Only desktop pointer devices use this.\\n     */\\n\\n    const enableCardTilt = () => {\\n\\n        if (\\n            !window.matchMedia(\\n                \\\"(pointer:fine)\\\"\\n            ).matches\\n        ) {\\n            return;\\n        }\\n\\n\\n        if (\\n            window.matchMedia(\\n                \\\"(prefers-reduced-motion: reduce)\\\"\\n            ).matches\\n        ) {\\n            return;\\n        }\\n\\n\\n        track\\n        .querySelectorAll(\\\".product\\\")\\n        .forEach((card) => {\\n\\n            let frame = null;\\n\\n\\n            card.addEventListener(\\n                \\\"pointermove\\\",\\n                (event) => {\\n\\n                    if (frame) {\\n                        cancelAnimationFrame(\\n                            frame\\n                        );\\n                    }\\n\\n\\n                    frame =\\n                        requestAnimationFrame(\\n                        () => {\\n\\n                            const rect =\\n                                card\\n                                .getBoundingClientRect();\\n\\n\\n                            const px =\\n                                (\\n                                    event.clientX\\n                                    - rect.left\\n                                )\\n                                / rect.width;\\n\\n\\n                            const py =\\n                                (\\n                                    event.clientY\\n                                    - rect.top\\n                                )\\n                                / rect.height;\\n\\n\\n                            /*\\n                             * Deliberately very small tilt.\\n                             * Keeps the cute premium feel\\n                             * instead of looking like a game UI.\\n                             */\\n\\n                            const ry =\\n                                (px - .5) * 4;\\n\\n\\n                            const rx =\\n                                (.5 - py) * 3;\\n\\n\\n                            card.style\\n                                .setProperty(\\n                                    \\\"--kb-rx\\\",\\n                                    rx.toFixed(2)\\n                                    + \\\"deg\\\"\\n                                );\\n\\n\\n                            card.style\\n                                .setProperty(\\n                                    \\\"--kb-ry\\\",\\n                                    ry.toFixed(2)\\n                                    + \\\"deg\\\"\\n                                );\\n                        }\\n                    );\\n                }\\n            );\\n\\n\\n            card.addEventListener(\\n                \\\"pointerleave\\\",\\n                () => {\\n\\n                    card.style\\n                        .setProperty(\\n                            \\\"--kb-rx\\\",\\n                            \\\"0deg\\\"\\n                        );\\n\\n\\n                    card.style\\n                        .setProperty(\\n                            \\\"--kb-ry\\\",\\n                            \\\"0deg\\\"\\n                        );\\n                }\\n            );\\n\\n        });\\n\\n    };\\n\\n\\n    /*\\n     * Fetch latest Bagisto products.\\n     */\\n\\n    fetch(\\n        \\\"/api/products?sort=created_at-desc&limit=12\\\",\\n        {\\n\\n            credentials:\\n                \\\"same-origin\\\",\\n\\n            headers: {\\n\\n                \\\"Accept\\\":\\n                    \\\"application/json\\\",\\n\\n                \\\"X-Requested-With\\\":\\n                    \\\"XMLHttpRequest\\\"\\n\\n            }\\n\\n        }\\n    )\\n\\n    .then((response) => {\\n\\n        if (!response.ok) {\\n\\n            throw new Error(\\n                \\\"Unable to load products\\\"\\n            );\\n        }\\n\\n\\n        return response.json();\\n\\n    })\\n\\n    .then((response) => {\\n\\n        const products =\\n            Array.isArray(\\n                response.data\\n            )\\n            ?\\n            response.data\\n            :\\n            [];\\n\\n\\n        if (!products.length) {\\n\\n            track.innerHTML =\\n                `\\n                <div class=\\\"msg\\\">\\n                    No new products found yet.\\n                </div>\\n                `;\\n\\n            return;\\n        }\\n\\n\\n        track.innerHTML =\\n            products\\n\\n            .map(\\n                (product) => {\\n\\n                    const url =\\n                        productURL(\\n                            product.url_key\\n                        );\\n\\n\\n                    const image =\\n                        productImage(\\n                            product\\n                        );\\n\\n\\n                    const isSale =\\n                        Boolean(\\n                            product.on_sale\\n                        );\\n\\n\\n                    const badge =\\n                        isSale\\n                        ? \\\"Sale\\\"\\n                        : \\\"New\\\";\\n\\n\\n                    const imageHTML =\\n                        image\\n                        ?\\n                        `\\n                        <img\\n                            loading=\\\"lazy\\\"\\n                            decoding=\\\"async\\\"\\n                            src=\\\"${escapeHTML(image)}\\\"\\n                            alt=\\\"${escapeHTML(\\n                                product.name\\n                                || \\\"Product\\\"\\n                            )}\\\"\\n                        >\\n                        `\\n                        :\\n                        `\\n                        <div\\n                            class=\\\"placeholder\\\"\\n                            aria-hidden=\\\"true\\\"\\n                        >\\n                            <span class=\\\"ph-heart\\\">\\n                                ♡\\n                            </span>\\n\\n                            <span>\\n                                Kawaii treasure\\n                            </span>\\n                        </div>\\n                        `;\\n\\n\\n                    /*\\n                     * price_html comes directly from\\n                     * your own Bagisto API.\\n                     */\\n\\n                    const price =\\n                        product.price_html\\n                        ||\\n                        escapeHTML(\\n                            product.min_price\\n                            || \\\"\\\"\\n                        );\\n\\n\\n                    return `\\n                    <article\\n                        class=\\\"product\\\"\\n                    >\\n\\n                        <div class=\\\"media\\\">\\n\\n                            <span\\n                                class=\\\"badge ${\\n                                    isSale\\n                                    ? \\\"sale\\\"\\n                                    : \\\"\\\"\\n                                }\\\"\\n                            >\\n                                ${escapeHTML(\\n                                    badge\\n                                )}\\n                            </span>\\n\\n\\n                            <a\\n                                href=\\\"${escapeHTML(\\n                                    url\\n                                )}\\\"\\n                            >\\n\\n                                ${imageHTML}\\n\\n                            </a>\\n\\n                        </div>\\n\\n\\n                        <div class=\\\"info\\\">\\n\\n                            <a\\n                                href=\\\"${escapeHTML(\\n                                    url\\n                                )}\\\"\\n                            >\\n\\n                                <div class=\\\"name\\\">\\n\\n                                    ${escapeHTML(\\n                                        product.name\\n                                        || \\\"Product\\\"\\n                                    )}\\n\\n                                </div>\\n\\n                            </a>\\n\\n\\n                            <div class=\\\"bottom\\\">\\n\\n                                <div class=\\\"price\\\">\\n\\n                                    ${price}\\n\\n                                </div>\\n\\n\\n                                <a\\n                                    class=\\\"heart\\\"\\n                                    href=\\\"${escapeHTML(\\n                                        url\\n                                    )}\\\"\\n                                    aria-label=\\\"View ${\\n                                        escapeHTML(\\n                                            product.name\\n                                            || \\\"product\\\"\\n                                        )\\n                                    }\\\"\\n                                >\\n                                    ♡\\n                                </a>\\n\\n                            </div>\\n\\n                        </div>\\n\\n                    </article>\\n                    `;\\n\\n                }\\n            )\\n\\n            .join(\\\"\\\");\\n\\n\\n        enableCardTilt();\\n\\n    })\\n\\n    .catch((error) => {\\n\\n        console.error(\\n            \\\"Kawaii Blessings Just Landed:\\\",\\n            error\\n        );\\n\\n\\n        track.innerHTML =\\n            `\\n            <div class=\\\"msg\\\">\\n                Products could not be loaded.\\n            </div>\\n            `;\\n\\n    });\\n\\n\\n    /*\\n     * Carousel navigation.\\n     */\\n\\n    const scrollAmount = () => {\\n\\n        return Math.max(\\n            260,\\n            track.clientWidth * .82\\n        );\\n\\n    };\\n\\n\\n    leftButton\\n    .addEventListener(\\n        \\\"click\\\",\\n        () => {\\n\\n            track.scrollBy({\\n\\n                left:\\n                    -scrollAmount(),\\n\\n                behavior:\\n                    \\\"smooth\\\"\\n\\n            });\\n\\n        }\\n    );\\n\\n\\n    rightButton\\n    .addEventListener(\\n        \\\"click\\\",\\n        () => {\\n\\n            track.scrollBy({\\n\\n                left:\\n                    scrollAmount(),\\n\\n                behavior:\\n                    \\\"smooth\\\"\\n\\n            });\\n\\n        }\\n    );\\n\\n})();\\n</script>\\n\\n</body>\\n</html>\"}',NULL),(162,207,'ar','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(163,207,'default','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(164,207,'nl','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(165,207,'tr','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(166,207,'fr','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(167,207,'de','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(168,207,'es','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(169,207,'zh_CN','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(170,207,'pt_BR','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(171,207,'ja','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(172,207,'it','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(173,207,'he','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(174,207,'pl','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(175,207,'fa','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(176,207,'hi','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(177,207,'uk','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(178,207,'ru','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(179,207,'vi','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(180,207,'ko','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(181,207,'bn','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(182,207,'sv','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kb