us-within {\\n\\n    transform:\\n        translateY(-2px)\\n        scale(1.007);\\n\\n    border-color:\\n\\n        rgba(210,166,78,.65);\\n\\n    box-shadow:\\n\\n        0 12px 27px\\n        rgba(187, 116, 138, .11),\\n\\n        0 0 0 3px\\n        rgba(234, 205, 140, .08),\\n\\n        0 0 22px\\n        rgba(236, 207, 145, .10);\\n}\\n\\n\\n/* input */\\n\\n#kb-community-section input {\\n\\n    width: 100%;\\n\\n    min-width: 0;\\n\\n    border: 0;\\n\\n    outline: none;\\n\\n    background: transparent;\\n\\n    padding:\\n\\n        0\\n        16px;\\n\\n    color: #4d3a40;\\n\\n    font-size: 10.5px;\\n}\\n\\n\\n#kb-community-section input::placeholder {\\n\\n    color: #8d777f;\\n\\n    transition:\\n\\n        color .25s ease,\\n\\n        transform .25s ease;\\n}\\n\\n\\n#kb-community-section input:focus::placeholder {\\n\\n    color: #b59ca5;\\n}\\n\\n\\n/* =========================================================\\n   PREMIUM GOLD SUBSCRIBE BUTTON\\n   ========================================================= */\\n\\n#kb-community-section button {\\n\\n    position: relative;\\n\\n    overflow: hidden;\\n\\n    border: 0;\\n\\n    cursor: pointer;\\n\\n    color: #fff;\\n\\n    background:\\n\\n        linear-gradient(\\n            180deg,\\n            #f5dea4 0%,\\n            #d9ad55 48%,\\n            #c79137 100%\\n        );\\n\\n    font-size: 10.5px;\\n\\n    font-weight: 850;\\n\\n    letter-spacing: .01em;\\n\\n    text-shadow:\\n\\n        0 1px 1px\\n        rgba(112, 74, 12, .16);\\n\\n    box-shadow:\\n\\n        inset 0 1px 0\\n        rgba(255,255,255,.62),\\n\\n        -3px 0 9px\\n        rgba(204, 158, 67, .10);\\n\\n    transition:\\n\\n        filter .25s ease,\\n\\n        transform .25s ease,\\n\\n        box-shadow .25s ease;\\n}\\n\\n\\n/* gold shine */\\n\\n#kb-community-section button::before {\\n\\n    content: \\\"\\\";\\n\\n    position: absolute;\\n\\n    top: -90%;\\n\\n    left: -55%;\\n\\n    width: 36%;\\n\\n    height: 280%;\\n\\n    background:\\n\\n        linear-gradient(\\n            90deg,\\n            transparent,\\n            rgba(255,255,255,.72),\\n            transparent\\n        );\\n\\n    transform:\\n\\n        rotate(18deg)\\n        translateX(-160%);\\n\\n    transition:\\n\\n        transform .75s ease;\\n\\n    pointer-events: none;\\n}\\n\\n\\n/* gentle idle glow */\\n\\n#kb-community-section button::after {\\n\\n    content: \\\"\\\";\\n\\n    position: absolute;\\n\\n    inset: 0;\\n\\n    border-radius: inherit;\\n\\n    box-shadow:\\n\\n        inset 0 0 13px\\n        rgba(255,255,255,.10);\\n\\n    animation:\\n\\n        kbButtonGlow\\n        3.8s\\n        ease-in-out\\n        infinite;\\n}\\n\\n\\n/* button hover */\\n\\n#kb-community-section button:hover {\\n\\n    filter:\\n\\n        saturate(1.08)\\n        brightness(1.035);\\n\\n    transform:\\n        scale(1.035);\\n\\n    box-shadow:\\n\\n        inset 0 1px 0\\n        rgba(255,255,255,.78),\\n\\n        0 8px 19px\\n        rgba(195, 143, 39, .28),\\n\\n        0 0 17px\\n        rgba(241, 211, 145, .20);\\n}\\n\\n\\n#kb-community-section button:hover::before {\\n\\n    transform:\\n\\n        rotate(18deg)\\n        translateX(530%);\\n}\\n\\n\\n/* =========================================================\\n   PERKS\\n   ========================================================= */\\n\\n#kb-community-section .perks {\\n\\n    margin-top: 18px;\\n\\n    display: grid;\\n\\n    grid-template-columns:\\n        repeat(4, max-content);\\n\\n    justify-content: center;\\n\\n    gap: 26px;\\n}\\n\\n\\n#kb-community-section .perk {\\n\\n    display: inline-flex;\\n\\n    align-items: center;\\n\\n    gap: 7px;\\n\\n    padding:\\n\\n        4px\\n        7px;\\n\\n    border-radius: 999px;\\n\\n    color: #514047;\\n\\n    font-size: 9.5px;\\n\\n    font-weight: 600;\\n\\n    white-space: nowrap;\\n\\n    transition:\\n\\n        transform .28s ease,\\n\\n        color .28s ease,\\n\\n        background .28s ease,\\n\\n        box-shadow .28s ease;\\n}\\n\\n\\n/* individual idle animations */\\n\\n#kb-community-section .perk:nth-child(1) {\\n    animation:\\n        kbPerkFloat\\n        5.2s\\n        ease-in-out\\n        infinite;\\n}\\n\\n#kb-community-section .perk:nth-child(2) {\\n    animation:\\n        kbPerkFloat\\n        5.8s\\n        ease-in-out\\n        infinite .7s;\\n}\\n\\n#kb-community-section .perk:nth-child(3) {\\n    animation:\\n        kbPerkFloat\\n        6.2s\\n        ease-in-out\\n        infinite 1.4s;\\n}\\n\\n#kb-community-section .perk:nth-child(4) {\\n    animation:\\n        kbPerkFloat\\n        5.5s\\n        ease-in-out\\n        infinite 2s;\\n}\\n\\n\\n/* hover */\\n\\n#kb-community-section .perk:hover {\\n\\n    transform:\\n        translateY(-4px)\\n        scale(1.04);\\n\\n    color: #c38b30;\\n\\n    background:\\n        rgba(255,255,255,.66);\\n\\n    box-shadow:\\n\\n        0 7px 16px\\n        rgba(201, 135, 158, .07);\\n}\\n\\n\\n/* perk icons */\\n\\n#kb-community-section .perk svg {\\n\\n    width: 27px;\\n    height: 27px;\\n\\n    fill: none;\\n\\n    stroke: #ed789e;\\n\\n    stroke-width: 1.6;\\n\\n    stroke-linecap: round;\\n    stroke-linejoin: round;\\n\\n    transition:\\n\\n        stroke .28s ease,\\n\\n        transform .28s ease,\\n\\n        filter .28s ease;\\n}\\n\\n\\n#kb-community-section .perk:hover svg {\\n\\n    stroke: var(--gold);\\n\\n    transform:\\n        rotate(-5deg)\\n        scale(1.10);\\n\\n    filter:\\n\\n        drop-shadow(\\n            0 3px 5px\\n            rgba(198, 149, 53, .18)\\n        );\\n}\\n\\n\\n/* =========================================================\\n   SUCCESS NOTE\\n   ========================================================= */\\n\\n#kb-community-section .note {\\n\\n    min-height: 16px;\\n\\n    margin-top: 8px;\\n\\n    color: #c58d32;\\n\\n    font-size: 9px;\\n\\n    font-weight: 700;\\n\\n    opacity: 0;\\n\\n    transform:\\n        translateY(5px)\\n        scale(.96);\\n\\n    transition:\\n\\n        opacity .3s ease,\\n\\n        transform .3s ease;\\n}\\n\\n\\n#kb-community-section .note.show {\\n\\n    opacity: 1;\\n\\n    transform: none;\\n\\n    animation:\\n\\n        kbSuccessPulse\\n        1.2s\\n        ease-in-out\\n        1;\\n}\\n\\n\\n/* =========================================================\\n   FLOATING DECORATIONS\\n   ========================================================= */\\n\\n#kb-community-section .floating {\\n\\n    position: absolute;\\n\\n    z-index: 5;\\n\\n    pointer-events: none;\\n\\n    will-change:\\n        transform,\\n        opacity;\\n}\\n\\n\\n/* sparkles */\\n\\n#kb-community-section .sparkle {\\n\\n    color: var(--gold);\\n\\n    font-size: 16px;\\n\\n    animation:\\n\\n        kbSparkle\\n        4s\\n        ease-in-out\\n        infinite;\\n}\\n\\n\\n#kb-community-section .sp1 {\\n\\n    left: 28%;\\n    top: 21px;\\n}\\n\\n\\n#kb-community-section .sp2 {\\n\\n    right: 28%;\\n    top: 48px;\\n\\n    animation-delay: 1.2s;\\n}\\n\\n\\n#kb-community-section .sp3 {\\n\\n    left: 36%;\\n    bottom: 26px;\\n\\n    animation-delay: 2s;\\n}\\n\\n\\n/* hearts */\\n\\n#kb-community-section .float-heart {\\n\\n    color:\\n        rgba(235,111,150,.42);\\n\\n    font-size: 19px;\\n\\n    animation:\\n\\n        kbFloatingHeart\\n        6.5s\\n        ease-in-out\\n        infinite;\\n}\\n\\n\\n#kb-community-section .heart1 {\\n\\n    left: 17%;\\n    top: 55px;\\n}\\n\\n\\n#kb-community-section .heart2 {\\n\\n    right: 14%;\\n    bottom: 25px;\\n\\n    animation-delay: 2.2s;\\n}\\n\\n\\n/* petals */\\n\\n#kb-community-section .petal {\\n\\n    width: 11px;\\n    height: 17px;\\n\\n    border-radius:\\n        70%\\n        30%\\n        70%\\n        30%;\\n\\n    background:\\n\\n        linear-gradient(\\n            135deg,\\n            rgba(255,255,255,.95),\\n            rgba(241,156,187,.70)\\n        );\\n\\n    opacity: .52;\\n\\n    animation:\\n\\n        kbPetalDrift\\n        9s\\n        ease-in-out\\n        infinite;\\n}\\n\\n\\n#kb-community-section .petal1 {\\n\\n    left: 41%;\\n    top: 15px;\\n}\\n\\n\\n#kb-community-section .petal2 {\\n\\n    right: 37%;\\n    top: 30px;\\n\\n    animation-delay: 2.4s;\\n}\\n\\n\\n#kb-community-section .petal3 {\\n\\n    left: 47%;\\n    bottom: 22px;\\n\\n    animation-delay: 4.2s;\\n}\\n\\n\\n/* =========================================================\\n   KEYFRAMES\\n   ========================================================= */\\n\\n@keyframes kbCommunityGlow {\\n\\n    0%,\\n    100% {\\n\\n        transform:\\n            translate(-50%, -50%)\\n            scale(.96);\\n\\n        opacity: .50;\\n    }\\n\\n    50% {\\n\\n        transform:\\n            translate(-48%, -52%)\\n            scale(1.08);\\n\\n        opacity: .85;\\n    }\\n}\\n\\n\\n@keyframes kbLeftArtFloat {\\n\\n    0%,\\n    100% {\\n\\n        transform:\\n            translate3d(\\n                var(--art-x),\\n                var(--art-y),\\n                0\\n            )\\n\\n            scale(1);\\n    }\\n\\n    50% {\\n\\n        transform:\\n            translate3d(\\n                calc(var(--art-x) + 5px),\\n                calc(var(--art-y) - 6px),\\n                0\\n            )\\n\\n            scale(1.018);\\n    }\\n}\\n\\n\\n@keyframes kbRightArtFloat {\\n\\n    0%,\\n    100% {\\n\\n        transform:\\n            translate3d(\\n                var(--art-x),\\n                var(--art-y),\\n                0\\n            )\\n\\n            scale(1);\\n    }\\n\\n    50% {\\n\\n        transform:\\n            translate3d(\\n                calc(var(--art-x) - 6px),\\n                calc(var(--art-y) - 5px),\\n                0\\n            )\\n\\n            scale(1.018);\\n    }\\n}\\n\\n\\n@keyframes kbTitleFloat {\\n\\n    0%,\\n    100% {\\n\\n        transform:\\n            translateY(0);\\n\\n        text-shadow:\\n            0 1px 0\\n            rgba(255,255,255,.95);\\n    }\\n\\n    50% {\\n\\n        transform:\\n            translateY(-2px);\\n\\n        text-shadow:\\n\\n            0 1px 0\\n            rgba(255,255,255,.96),\\n\\n            0 0 14px\\n            rgba(224, 103, 142, .09);\\n    }\\n}\\n\\n\\n@keyframes kbHeadingSparkle {\\n\\n    0%,\\n    100% {\\n\\n        opacity: .35;\\n\\n        transform:\\n\\n            translateY(-9px)\\n            scale(.75)\\n            rotate(0deg);\\n    }\\n\\n    50% {\\n\\n        opacity: 1;\\n\\n        transform:\\n\\n            translateY(-10px)\\n            scale(1.18)\\n            rotate(20deg);\\n    }\\n}\\n\\n\\n@keyframes kbUnderlinePulse {\\n\\n    0%,\\n    100% {\\n\\n        opacity: .2;\\n\\n        transform:\\n            scaleX(.7);\\n    }\\n\\n    50% {\\n\\n        opacity: .8;\\n\\n        transform:\\n            scaleX(1);\\n    }\\n}\\n\\n\\n@keyframes kbCopyFloat {\\n\\n    0%,\\n    100% {\\n\\n        transform:\\n            translateY(0);\\n    }\\n\\n    50% {\\n\\n        transform:\\n            translateY(-1.5px);\\n    }\\n}\\n\\n\\n@keyframes kbButtonGlow {\\n\\n    0%,\\n    100% {\\n\\n        opacity: .35;\\n    }\\n\\n    50% {\\n\\n        opacity: .85;\\n    }\\n}\\n\\n\\n@keyframes kbPerkFloat {\\n\\n    0%,\\n    100% {\\n\\n        transform:\\n            translateY(0);\\n    }\\n\\n    50% {\\n\\n        transform:\\n            translateY(-3px);\\n    }\\n}\\n\\n\\n@keyframes kbSuccessPulse {\\n\\n    0% {\\n\\n        transform:\\n            scale(.95);\\n    }\\n\\n    50% {\\n\\n        transform:\\n            scale(1.04);\\n    }\\n\\n    100% {\\n\\n        transform:\\n            scale(1);\\n    }\\n}\\n\\n\\n@keyframes kbSparkle {\\n\\n    0%,\\n    100% {\\n\\n        opacity: .25;\\n\\n        transform:\\n\\n            scale(.72)\\n            rotate(0deg);\\n    }\\n\\n    50% {\\n\\n        opacity: .95;\\n\\n        transform:\\n\\n            scale(1.18)\\n            rotate(18deg);\\n    }\\n}\\n\\n\\n@keyframes kbFloatingHeart {\\n\\n    0%,\\n    100% {\\n\\n        opacity: .25;\\n\\n        transform:\\n\\n            translateY(0)\\n            rotate(-5deg)\\n            scale(.90);\\n    }\\n\\n    50% {\\n\\n        opacity: .65;\\n\\n        transform:\\n\\n            translateY(-11px)\\n            rotate(6deg)\\n            scale(1.08);\\n    }\\n}\\n\\n\\n@keyframes kbPetalDrift {\\n\\n    0%,\\n    100% {\\n\\n        opacity: .20;\\n\\n        transform:\\n\\n            translate3d(0,0,0)\\n            rotate(10deg);\\n    }\\n\\n    35% {\\n\\n        opacity: .60;\\n\\n        transform:\\n\\n            translate3d(8px,8px,0)\\n            rotate(75deg);\\n    }\\n\\n    70% {\\n\\n        opacity: .45;\\n\\n        transform:\\n\\n            translate3d(-5px,15px,0)\\n            rotate(145deg);\\n    }\\n}\\n\\n\\n/* =========================================================\\n   TABLET\\n   ========================================================= */\\n\\n@media (max-width:1050px) {\\n\\n    #kb-community-section .center {\\n\\n        width:60%;\\n    }\\n\\n\\n    #kb-community-section .art {\\n\\n        width:34%;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   MOBILE\\n   ========================================================= */\\n\\n@media (max-width:780px) {\\n\\n    #kb-community-section {\\n\\n        padding:\\n            14px\\n            12px;\\n    }\\n\\n\\n    #kb-community-section .community {\\n\\n        min-height:430px;\\n    }\\n\\n\\n    #kb-community-section .center {\\n\\n        width:100%;\\n\\n        min-height:240px;\\n\\n        padding:\\n            27px\\n            18px\\n            12px;\\n    }\\n\\n\\n    #kb-community-section .art {\\n\\n        top:auto;\\n\\n        bottom:0;\\n\\n        width:50%;\\n\\n        height:48%;\\n    }\\n\\n\\n    #kb-community-section .left,\\n    #kb-community-section .right {\\n\\n        mask-image:\\n\\n            linear-gradient(\\n                0deg,\\n                #000 0%,\\n                #000 70%,\\n                transparent 100%\\n            );\\n\\n        -webkit-mask-image:\\n\\n            linear-gradient(\\n                0deg,\\n                #000 0%,\\n                #000 70%,\\n                transparent 100%\\n            );\\n    }\\n\\n\\n    #kb-community-section .perks {\\n\\n        grid-template-columns:\\n            repeat(2, max-content);\\n\\n        gap:\\n            10px\\n            18px;\\n    }\\n\\n\\n    #kb-community-section .floating {\\n\\n        opacity: .55;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   SMALL MOBILE\\n   ========================================================= */\\n\\n@media (max-width:520px) {\\n\\n    #kb-community-section form {\\n\\n        grid-template-columns:\\n            1fr 95px;\\n    }\\n\\n\\n    #kb-community-section .perks {\\n\\n        gap:\\n            9px\\n            12px;\\n    }\\n\\n\\n    #kb-community-section .perk {\\n\\n        font-size:8.8px;\\n    }\\n\\n\\n    #kb-community-section h2 {\\n\\n        font-size:27px;\\n    }\\n\\n\\n    #kb-community-section h2::before,\\n    #kb-community-section h2::after {\\n\\n        margin:\\n            0\\n            6px;\\n\\n        font-size:11px;\\n    }\\n}\\n\\n\\n/* =========================================================\\n   ACCESSIBILITY\\n   ========================================================= */\\n\\n@media (prefers-reduced-motion:reduce) {\\n\\n    #kb-community-section *,\\n    #kb-community-section *::before,\\n    #kb-community-section *::after {\\n\\n        animation:none !important;\\n\\n        transition:none !important;\\n    }\\n\\n\\n    #kb-community-section .community {\\n\\n        opacity:1 !important;\\n\\n        transform:none !important;\\n    }\\n}\\n</style>\\n</head>\\n\\n\\n<body>\\n\\n\\n<section id=\\\"kb-community-section\\\">\\n\\n    <div class=\\\"inner\\\">\\n\\n\\n        <section class=\\\"community\\\">\\n\\n\\n            <!-- FLOATING DECOR -->\\n\\n            <span class=\\\"floating sparkle sp1\\\">✦</span>\\n\\n            <span class=\\\"floating sparkle sp2\\\">✧</span>\\n\\n            <span class=\\\"floating sparkle sp3\\\">✦</span>\\n\\n\\n            <span class=\\\"floating float-heart heart1\\\">♡</span>\\n\\n            <span class=\\\"floating float-heart heart2\\\">♡</span>\\n\\n\\n            <span class=\\\"floating petal petal1\\\"></span>\\n\\n            <span class=\\\"floating petal petal2\\\"></span>\\n\\n            <span class=\\\"floating petal petal3\\\"></span>\\n\\n\\n\\n            <!-- LEFT ART -->\\n\\n            <img\\n\\n                class=\\\"art left\\\"\\n\\n                src=\\\"/storage/themes/default/sections/209/IDVcm1GwTt7YZh4bLOCMLHYPr4HLJgJo8ehNJIxK.webp\\\"\\n\\n                alt=\\\"\\\"\\n\\n                aria-hidden=\\\"true\\\"\\n\\n            >\\n\\n\\n\\n            <!-- CENTER -->\\n\\n            <div class=\\\"center\\\">\\n\\n\\n                <h2>\\n\\n                    <span>\\n                        Join the Kawaii Community\\n                    </span>\\n\\n                </h2>\\n\\n\\n                <p class=\\\"copy\\\">\\n\\n                    Be the first to know about\\n                    new arrivals, exclusive offers\\n\\n                    <br>\\n\\n                    and special surprises\\n                    just for you!\\n\\n                </p>\\n\\n\\n                <form id=\\\"kb-community-form\\\">\\n\\n\\n                    <input\\n\\n                        type=\\\"email\\\"\\n\\n                        placeholder=\\\"Enter your email address\\\"\\n\\n                        autocomplete=\\\"email\\\"\\n\\n                        required\\n\\n                    >\\n\\n\\n                    <button type=\\\"submit\\\">\\n\\n                        Subscribe\\n\\n                    </button>\\n\\n\\n                </form>\\n\\n\\n\\n                <div class=\\\"perks\\\">\\n\\n\\n                    <span class=\\\"perk\\\">\\n\\n                        <svg viewBox=\\\"0 0 24 24\\\">\\n\\n                            <rect\\n                                x=\\\"3\\\"\\n                                y=\\\"9\\\"\\n                                width=\\\"18\\\"\\n                                height=\\\"12\\\"\\n                                rx=\\\"1\\\"\\n                            />\\n\\n                            <path\\n                                d=\\\"M12 9v12M3 13h18\\\"\\n                            />\\n\\n                        </svg>\\n\\n                        Exclusive Offers\\n\\n                    </span>\\n\\n\\n\\n                    <span class=\\\"perk\\\">\\n\\n                        <svg viewBox=\\\"0 0 24 24\\\">\\n\\n                            <circle\\n                                cx=\\\"12\\\"\\n                                cy=\\\"12\\\"\\n                                r=\\\"2\\\"\\n                            />\\n\\n                            <path\\n                                d=\\\"M12 10c-3-5-7-4-7-1 0 2 2 3 5 3-5 3-3 7 0 7 2 0 3-2 2-5 3 5 7 3 7 0 0-2-2-3-5-2 5-3 3-7 0-7-2 0-3 2-2 5Z\\\"\\n                            />\\n\\n                        </svg>\\n\\n                        New Arrivals\\n\\n                    </span>\\n\\n\\n\\n                    <span class=\\\"perk\\\">\\n\\n                        <svg viewBox=\\\"0 0 24 24\\\">\\n\\n                            <path\\n                                d=\\\"M20 4.5c-2-2-5.2-1.7-7 .4L12 6l-1-1.1C9.2 2.8 6 2.5 4 4.5c-2.2 2.2-2 5.7.2 7.8L12 20l7.8-7.7C22 10.2 22.2 6.7 20 4.5Z\\\"\\n                            />\\n\\n                        </svg>\\n\\n                        Kawaii Surprises\\n\\n                    </span>\\n\\n\\n\\n                    <span class=\\\"perk\\\">\\n\\n                        <svg viewBox=\\\"0 0 24 24\\\">\\n\\n                            <path\\n                                d=\\\"m4 18-1-9 5 4 4-8 4 8 5-4-1 9Z\\\"\\n                            />\\n\\n                            <path\\n                                d=\\\"M5 21h14\\\"\\n                            />\\n\\n                        </svg>\\n\\n                        VIP Perks\\n\\n                    </span>\\n\\n\\n                </div>\\n\\n\\n\\n                <div\\n\\n                    id=\\\"kb-community-note\\\"\\n\\n                    class=\\\"note\\\"\\n\\n                >\\n\\n                    Thank you!\\n                    You’re on the kawaii list ♡\\n\\n                </div>\\n\\n\\n            </div>\\n\\n\\n\\n            <!-- RIGHT ART -->\\n\\n            <img\\n\\n                class=\\\"art right\\\"\\n\\n                src=\\\"/storage/themes/default/sections/209/RjcrxLMFudwbJyl8asC7Ry1pc43cI7pI2qdjRJQP.webp\\\"\\n\\n                alt=\\\"\\\"\\n\\n                aria-hidden=\\\"true\\\"\\n\\n            >\\n\\n\\n        </section>\\n\\n\\n    </div>\\n\\n</section>\\n\\n\\n\\n<script>\\n(function () {\\n\\n\\n    const section =\\n        document.getElementById(\\n            \\\"kb-community-section\\\"\\n        );\\n\\n\\n    if (!section) return;\\n\\n\\n    const community =\\n        section.querySelector(\\n            \\\".community\\\"\\n        );\\n\\n\\n    const leftArt =\\n        section.querySelector(\\n            \\\".left\\\"\\n        );\\n\\n\\n    const rightArt =\\n        section.querySelector(\\n            \\\".right\\\"\\n        );\\n\\n\\n\\n    /* =====================================================\\n       SCROLL REVEAL\\n       ===================================================== */\\n\\n    if (\\n        \\\"IntersectionObserver\\\"\\n        in window\\n    ) {\\n\\n\\n        const observer =\\n            new IntersectionObserver(\\n\\n                function (entries) {\\n\\n\\n                    entries.forEach(\\n\\n                        function (entry) {\\n\\n\\n                            if (\\n                                entry.isIntersecting\\n                            ) {\\n\\n\\n                                entry.target\\n                                    .classList\\n                                    .add(\\n                                        \\\"is-visible\\\"\\n                                    );\\n\\n\\n                                observer\\n                                    .unobserve(\\n                                        entry.target\\n                                    );\\n\\n                            }\\n\\n\\n                        }\\n\\n                    );\\n\\n\\n                },\\n\\n                {\\n\\n                    threshold: .16\\n\\n                }\\n\\n            );\\n\\n\\n        observer.observe(\\n            community\\n        );\\n\\n\\n    } else {\\n\\n\\n        community\\n            .classList\\n            .add(\\n                \\\"is-visible\\\"\\n            );\\n\\n\\n    }\\n\\n\\n\\n    /* =====================================================\\n       MOUSE LIGHT + ART PARALLAX\\n       ===================================================== */\\n\\n    if (\\n        window.matchMedia(\\n            \\\"(pointer:fine)\\\"\\n        ).matches\\n    ) {\\n\\n\\n        section.addEventListener(\\n\\n            \\\"pointermove\\\",\\n\\n            function (event) {\\n\\n\\n                const rect =\\n                    section.getBoundingClientRect();\\n\\n\\n                const x =\\n                    event.clientX\\n                    - rect.left;\\n\\n\\n                const y =\\n                    event.clientY\\n                    - rect.top;\\n\\n\\n                section.style\\n                    .setProperty(\\n                        \\\"--mx\\\",\\n                        x + \\\"px\\\"\\n                    );\\n\\n\\n                section.style\\n                    .setProperty(\\n                        \\\"--my\\\",\\n                        y + \\\"px\\\"\\n                    );\\n\\n\\n                const nx =\\n                    x / rect.width\\n                    - .5;\\n\\n\\n                const ny =\\n                    y / rect.height\\n                    - .5;\\n\\n\\n                leftArt.style\\n                    .setProperty(\\n                        \\\"--art-x\\\",\\n                        (nx * 5)\\n                        + \\\"px\\\"\\n                    );\\n\\n\\n                leftArt.style\\n                    .setProperty(\\n                        \\\"--art-y\\\",\\n                        (ny * 4)\\n                        + \\\"px\\\"\\n                    );\\n\\n\\n                rightArt.style\\n                    .setProperty(\\n                        \\\"--art-x\\\",\\n                        (nx * -5)\\n                        + \\\"px\\\"\\n                    );\\n\\n\\n                rightArt.style\\n                    .setProperty(\\n                        \\\"--art-y\\\",\\n                        (ny * 4)\\n                        + \\\"px\\\"\\n                    );\\n\\n\\n            }\\n\\n        );\\n\\n\\n        section.addEventListener(\\n\\n            \\\"pointerleave\\\",\\n\\n            function () {\\n\\n\\n                leftArt.style\\n                    .setProperty(\\n                        \\\"--art-x\\\",\\n                        \\\"0px\\\"\\n                    );\\n\\n\\n                leftArt.style\\n                    .setProperty(\\n                        \\\"--art-y\\\",\\n                        \\\"0px\\\"\\n                    );\\n\\n\\n                rightArt.style\\n                    .setProperty(\\n                        \\\"--art-x\\\",\\n                        \\\"0px\\\"\\n                    );\\n\\n\\n                rightArt.style\\n                    .setProperty(\\n                        \\\"--art-y\\\",\\n                        \\\"0px\\\"\\n                    );\\n\\n\\n            }\\n\\n        );\\n\\n\\n    }\\n\\n\\n\\n    /* =====================================================\\n       NEWSLETTER SUBMIT\\n       ===================================================== */\\n\\n    const form =\\n        document.getElementById(\\n            \\\"kb-community-form\\\"\\n        );\\n\\n\\n    const note =\\n        document.getElementById(\\n            \\\"kb-community-note\\\"\\n        );\\n\\n\\n    form.addEventListener(\\n\\n        \\\"submit\\\",\\n\\n        function (event) {\\n\\n\\n            event.preventDefault();\\n\\n\\n            const input =\\n                form.querySelector(\\n                    \'input[type=\\\"email\\\"]\'\\n                );\\n\\n\\n            if (\\n                !input.checkValidity()\\n            ) {\\n\\n\\n                input.reportValidity();\\n\\n\\n                return;\\n            }\\n\\n\\n            const button =\\n                form.querySelector(\\n                    \\\"button\\\"\\n                );\\n\\n\\n            const oldText =\\n                button.textContent;\\n\\n\\n            button.textContent =\\n                \\\"Welcome ♡\\\";\\n\\n\\n            note\\n                .classList\\n                .add(\\n                    \\\"show\\\"\\n                );\\n\\n\\n            input.value = \\\"\\\";\\n\\n\\n            clearTimeout(\\n                form._kbTimer\\n            );\\n\\n\\n            form._kbTimer =\\n                setTimeout(\\n\\n                    function () {\\n\\n\\n                        note\\n                            .classList\\n                            .remove(\\n                                \\\"show\\\"\\n                            );\\n\\n\\n                        button.textContent =\\n                            oldText;\\n\\n\\n                    },\\n\\n                    3500\\n\\n                );\\n\\n\\n        }\\n\\n    );\\n\\n\\n})();\\n</script>\\n\\n\\n</body>\\n</html>\"}',NULL),(206,209,'ar','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(207,209,'default','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(208,209,'nl','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(209,209,'tr','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(210,209,'fr','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(211,209,'de','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(212,209,'es','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(213,209,'zh_CN','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(214,209,'pt_BR','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(215,209,'ja','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(216,209,'it','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(217,209,'he','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(218,209,'pl','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(219,209,'fa','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(220,209,'hi','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(221,209,'uk','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(222,209,'ru','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(223,209,'vi','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(224,209,'ko','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(225,209,'bn','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===\\\"/\\\"?s:\\\"/\\\"+s};\\n const catImg=c=>(c.logo&&(c.logo.large_image_url||c.logo.medium_image_url||c.logo.small_image_url||c.logo.original_image_url))||(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url||c.banner.small_image_url||c.banner.original_image_url))||\\\"\\\";\\n const prodImg=p=>p.base_image&&(p.base_image.medium_image_url||p.base_image.small_image_url||p.base_image.large_image_url||p.base_image.original_image_url)||\\\"\\\";\\n const get=async u=>{const r=await fetch(u,{credentials:\\\"same-origin\\\",headers:{Accept:\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"}});const j=await r.json();if(!r.ok)throw new Error(j.message||\\\"Request failed\\\");return j};\\n const show=m=>{toast.textContent=m;toast.classList.add(\\\"show\\\");clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove(\\\"show\\\"),2800)};\\n\\n async function loadCategories(){\\n  try{\\n   const j=await get(API.categories),incoming=Array.isArray(j.data)?j.data:[],map=new Map(incoming.map(c=>[norm(c.name),c]));\\n   let list=ORDER.map(n=>map.get(norm(n))).filter(Boolean);\\n   const ids=new Set(list.map(c=>c.id));incoming.forEach(c=>{if(!ids.has(c.id)&&c.parent_id)list.push(c)});\\n   renderCategories(list);renderTrends(list);renderPromo(list);\\n  }catch(e){grid.innerHTML=\'<div class=\\\"msg\\\">Categories could not be loaded.</div>\';trends.innerHTML=\'<div class=\\\"msg\\\">Collections unavailable.</div>\';console.error(e)}\\n }\\n\\n function renderCategories(list){\\n  if(!list.length){grid.innerHTML=\'<div class=\\\"msg\\\">No enabled categories found.</div>\';return}\\n  grid.innerHTML=list.map((c,i)=>{\\n   const im=catImg(c),name=c.name||\\\"Collection\\\";\\n   return `<a class=\\\"cat\\\" href=\\\"${esc(url(c.slug))}\\\">\\n    <div class=\\\"cat-media\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(name)}\\\">`:`<div class=\\\"msg\\\">${esc(name)}</div>`}</div>\\n    <div class=\\\"cat-body\\\"><h3>${esc(name)}</h3><p>${esc(DESC[name]||\\\"Explore this Kawaii Blessings collection.\\\")}</p>\\n    <div class=\\\"cat-foot\\\"><span>Explore collection</span><span>→</span></div></div></a>`\\n  }).join(\\\"\\\")\\n }\\n\\n function renderTrends(list){\\n  const m=new Map(list.map(c=>[norm(c.name),c]));let chosen=TREND.map(n=>m.get(norm(n))).filter(Boolean);\\n  list.forEach(c=>{if(chosen.length<6&&!chosen.some(x=>x.id===c.id))chosen.push(c)});\\n  trends.innerHTML=chosen.slice(0,6).map(c=>{const im=catImg(c);return `<a class=\\\"trend\\\" href=\\\"${esc(url(c.slug))}\\\">\\n   <div class=\\\"img\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`:\\\"♡\\\"}</div><h3>${esc(c.name)}</h3><p>Kawaii favorites</p></a>`}).join(\\\"\\\")\\n }\\n\\n function renderPromo(list){\\n  const c=list.find(x=>norm(x.name)===norm(\\\"Blind Box\\\"));if(!c)return;\\n  promoLink.href=url(c.slug);const im=(c.banner&&(c.banner.large_image_url||c.banner.medium_image_url))||catImg(c);\\n  if(im)promo.innerHTML=`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(c.name)}\\\">`\\n }\\n\\n async function loadProducts(){\\n  try{const j=await get(API.products);renderProducts(Array.isArray(j.data)?j.data:[])}\\n  catch(e){products.innerHTML=\'<div class=\\\"msg\\\">Products could not be loaded.</div>\';console.error(e)}\\n }\\n\\n function renderProducts(list){\\n  if(!list.length){products.innerHTML=\'<div class=\\\"msg\\\">No products found.</div>\';return}\\n  products.innerHTML=list.map(p=>{\\n   const u=url(p.url_key),im=prodImg(p),badge=p.on_sale?\\\"Sale\\\":(p.is_new?\\\"New\\\":\\\"\\\");\\n   return `<article class=\\\"product\\\">\\n    <div class=\\\"pm\\\">${badge?`<span class=\\\"badge\\\">${badge}</span>`:\\\"\\\"}<a href=\\\"${esc(u)}\\\">${im?`<img loading=\\\"lazy\\\" src=\\\"${esc(im)}\\\" alt=\\\"${esc(p.name)}\\\">`:\\\"\\\"}</a></div>\\n    <div class=\\\"pi\\\"><a href=\\\"${esc(u)}\\\"><div class=\\\"pn\\\">${esc(p.name)}</div></a><div class=\\\"price\\\">${p.price_html||esc(p.min_price||\\\"\\\")}</div>\\n    <div class=\\\"actions\\\">${p.is_saleable?`<button class=\\\"add\\\" data-add=\\\"${esc(p.id)}\\\" data-url=\\\"${esc(u)}\\\">Add to Cart</button>`:`<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">View</a>`}<a class=\\\"view\\\" href=\\\"${esc(u)}\\\">→</a></div></div></article>`\\n  }).join(\\\"\\\")\\n }\\n\\n async function add(btn){\\n  const id=Number(btn.dataset.add),fallback=btn.dataset.url||\\\"#\\\",old=btn.textContent,meta=document.querySelector(\'meta[name=\\\"csrf-token\\\"]\');\\n  btn.disabled=true;btn.textContent=\\\"Adding…\\\";\\n  try{\\n   const headers={Accept:\\\"application/json\\\",\\\"Content-Type\\\":\\\"application/json\\\",\\\"X-Requested-With\\\":\\\"XMLHttpRequest\\\"};if(meta&&meta.content)headers[\\\"X-CSRF-TOKEN\\\"]=meta.content;\\n   const r=await fetch(API.cart,{method:\\\"POST\\\",credentials:\\\"same-origin\\\",headers,body:JSON.stringify({product_id:id,quantity:1})});\\n   let j={};try{j=await r.json()}catch(_){}\\n   if(!r.ok){if(j.redirect_uri){location.href=j.redirect_uri;return}throw new Error(j.message||\\\"Please open the product to choose its options.\\\")}\\n   show(j.message||\\\"Added to your bag ♡\\\");btn.textContent=\\\"Added ♡\\\";\\n   setTimeout(()=>{btn.disabled=false;btn.textContent=old},1100)\\n  }catch(e){show(e.message);btn.disabled=false;btn.textContent=old;if(fallback!==\\\"#\\\")setTimeout(()=>location.href=fallback,900)}\\n }\\n\\n root.addEventListener(\\\"click\\\",e=>{const b=e.target.closest(\\\"[data-add]\\\");if(b){e.preventDefault();add(b)}});\\n const left=root.querySelector(\\\".left\\\"),right=root.querySelector(\\\".right\\\");\\n left.addEventListener(\\\"click\\\",()=>products.scrollBy({left:-Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n right.addEventListener(\\\"click\\\",()=>products.scrollBy({left:Math.max(280,products.clientWidth*.78),behavior:\\\"smooth\\\"}));\\n\\n loadCategories();loadProducts();\\n})();\\n</script>\\n</section>\"}',NULL),(226,209,'sv','{\"html\": \"<!-- Kawaii Blessings / Bagisto Static Content V2\\nPaste this entire block into Appearance > Theme > Static Content > HTML.\\nThis version is static-content-safe: it uses Bagisto\'s real storefront APIs because\\nBlade directives/components inside DB-stored Static Content HTML are not compiled.\\n-->\\n<section id=\\\"kbv2-home\\\">\\n<style>\\n#kbv2-home,#kbv2-home *{box-sizing:border-box}\\n#kbv2-home{\\n --pink:#ef739d;--pink2:#df5e89;--soft:#fff4f8;--text:#4a2e35;--muted:#826c73;\\n --gold:#d7ad54;--border:#f1dbe2;--shadow:0 16px 40px rgba(205,128,153,.10);\\n --r:24px;--max:1400px;\\n width:100%;padding:32px 18px 52px;color:var(--text);font-family:inherit;\\n background:radial-gradient(circle at 4% 5%,rgba(255,214,228,.32),transparent 20%),\\n linear-gradient(180deg,#fffafb,#fff7f9)\\n}\\n#kbv2-home a{text-decoration:none;color:inherit}\\n#kbv2-home button{font:inherit}\\n#kbv2-home .shell{max-width:var(--max);margin:auto;display:grid;gap:26px}\\n#kbv2-home .panel{padding:28px;border:1px solid var(--border);border-radius:var(--r);background:rgba(255,255,255,.84);box-shadow:var(--shadow)}\\n#kbv2-home .head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:20px}\\n#kbv2-home .kicker{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--pink2);margin-bottom:7px}\\n#kbv2-home .kicker:before,#kbv2-home .kicker:after{content:\\\"✦\\\";color:var(--gold);margin:0 6px}\\n#kbv2-home h2{margin:0;font:700 clamp(30px,3vw,45px)/1.05 Georgia,serif;color:#743449}\\n#kbv2-home .sub{margin:8px 0 0;max-width:760px;font-size:14px;line-height:1.65;color:var(--muted)}\\n#kbv2-home .pill{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border:1px solid #efccd8;border-radius:999px;background:#fff6f9;color:var(--pink2);font-size:13px;font-weight:800;white-space:nowrap}\\n#kbv2-home .primary{background:linear-gradient(#f58bab,#e96791);color:#fff;box-shadow:0 10px 23px rgba(229,93,137,.2)}\\n#kbv2-home .discover{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}\\n#kbv2-home .discover article{padding:21px;border:1px solid var(--border);border-radius:20px;background:linear-gradient(145deg,#fff,#fff4f7);transition:.22s}\\n#kbv2-home .discover article:hover,#kbv2-home .cat:hover,#kbv2-home .product:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\\n#kbv2-home .ico{width:46px;height:46px;display:grid;place-items:center;border-radius:16px;border:1px solid #f1d3dd;background:#fff4f8;color:var(--pink2);font-size:21px;margin-bottom:13px}\\n#kbv2-home h3{margin:0;color:#57333d}\\n#kbv2-home .discover h3{font-size:17px}\\n#kbv2-home .discover p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:7px 0 0}\\n#kbv2-home .trends{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}\\n#kbv2-home .trend{text-align:center}\\n#kbv2-home .trend .img{width:112px;max-width:100%;aspect-ratio:1;margin:0 auto 11px;padding:5px;border-radius:50%;border:1px solid #efc9d6;background:#fff4f8;overflow:hidden}\\n#kbv2-home .trend img{width:100%;height:100%;object-fit:cover;border-radius:50%}\\n#kbv2-home .trend h3{font-size:13px}\\n#kbv2-home .trend p{font-size:11px;color:var(--muted);margin:3px 0 0}\\n#kbv2-home .promo{overflow:hidden;border:1px solid var(--border);border-radius:var(--r);background:linear-gradient(135deg,#fff5f8,#ffe8ef);box-shadow:var(--shadow)}\\n#kbv2-home .promo-in{display:grid;grid-template-columns:.9fr 1.1fr;min-height:250px}\\n#kbv2-home .promo-copy{padding:32px 36px;display:flex;flex-direction:column;justify-content:center}\\n#kbv2-home .promo-copy small{font:italic 17px Georgia,serif;color:var(--pink2)}\\n#kbv2-home .promo-copy h2{font-size:clamp(34px,4vw,49px);margin:5px 0 10px}\\n#kbv2-home .promo-copy p{font-size:13px;line-height:1.6;color:var(--muted);margin:0 0 17px}\\n#kbv2-home .promo-media{min-height:250px;background:#fff1f5;position:relative}\\n#kbv2-home .promo-media img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}\\n#kbv2-home .promo-fallback{height:100%;min-height:250px;display:grid;place-items:center;font-size:70px}\\n#kbv2-home .categories{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\\n#kbv2-home .cat{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .cat-media{aspect-ratio:1.5/1;background:#fff1f5;overflow:hidden}\\n#kbv2-home .cat-media img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .cat:hover .cat-media img{transform:scale(1.045)}\\n#kbv2-home .cat-body{padding:14px 15px}\\n#kbv2-home .cat h3{font:700 17px/1.2 Georgia,serif}\\n#kbv2-home .cat p{font-size:11.5px;line-height:1.45;color:var(--muted);margin:6px 0 0}\\n#kbv2-home .cat-foot{display:flex;justify-content:space-between;align-items:center;margin-top:10px;color:var(--pink2);font-size:11.5px;font-weight:800}\\n#kbv2-home .products-wrap{position:relative}\\n#kbv2-home .products{display:grid;grid-auto-flow:column;grid-auto-columns:calc(20% - 14px);gap:17px;overflow:auto;scroll-behavior:smooth;scrollbar-width:none;padding:3px 2px 8px}\\n#kbv2-home .products::-webkit-scrollbar{display:none}\\n#kbv2-home .product{overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;transition:.22s}\\n#kbv2-home .pm{aspect-ratio:1/1.03;background:#fff3f7;position:relative;overflow:hidden}\\n#kbv2-home .pm img{width:100%;height:100%;object-fit:cover;transition:.35s}\\n#kbv2-home .product:hover .pm img{transform:scale(1.045)}\\n#kbv2-home .badge{position:absolute;left:9px;top:9px;padding:6px 9px;border-radius:999px;background:var(--pink);color:#fff;font-size:10px;font-weight:900}\\n#kbv2-home .pi{padding:13px}\\n#kbv2-home .pn{min-height:40px;font-size:13px;line-height:1.45;font-weight:750}\\n#kbv2-home .price{min-height:25px;margin-top:7px;font-size:14px;font-weight:800;color:#743449}\\n#kbv2-home .actions{display:grid;grid-template-columns:1fr 39px;gap:7px;margin-top:10px}\\n#kbv2-home .actions button,#kbv2-home .actions a{min-height:39px;display:grid;place-items:center;border:1px solid #efccd8;border-radius:12px;font-size:11.5px;font-weight:800}\\n#kbv2-home .add{background:linear-gradient(#f58bab,#e96791);color:#fff;cursor:pointer}\\n#kbv2-home .view{background:#fff5f8;color:var(--pink2)}\\n#kbv2-home .arrow{position:absolute;z-index:3;top:45%;transform:translateY(-50%);width:43px;height:43px;border:1px solid #edd1da;border-radius:50%;background:#fff;color:var(--pink2);box-shadow:var(--shadow);cursor:pointer;font-size:20px}\\n#kbv2-home .left{left:-12px}#kbv2-home .right{right:-12px}\\n#kbv2-home .values{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\\n#kbv2-home .value{padding:22px;border:1px solid var(--border);border-radius:21px;background:linear-gradient(135deg,#fff,#fff4f8);box-shadow:var(--shadow)}\\n#kbv2-home .value h3{font:700 24px Georgia,serif;color:#743449;margin:11px 0 6px}\\n#kbv2-home .value p{font-size:12.5px;line-height:1.55;color:var(--muted);margin:0}\\n#kbv2-home .msg{grid-column:1/-1;padding:20px;border:1px dashed #e9c5d1;border-radius:15px;background:#fff7f9;text-align:center;color:var(--muted);font-size:12px}\\n#kbv2-toast{position:fixed;right:18px;bottom:18px;z-index:99999;max-width:360px;padding:12px 15px;border:1px solid #edd1da;border-radius:14px;background:#fff;color:#59343e;box-shadow:var(--shadow);opacity:0;transform:translateY(8px);pointer-events:none;transition:.2s}\\n#kbv2-toast.show{opacity:1;transform:none}\\n@media(max-width:1150px){\\n #kbv2-home .discover{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .categories{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .trends{grid-template-columns:repeat(3,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(25% - 13px)}\\n}\\n@media(max-width:850px){\\n #kbv2-home .promo-in{grid-template-columns:1fr}\\n #kbv2-home .categories{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .products{grid-auto-columns:calc(33.333% - 12px)}\\n #kbv2-home .values{grid-template-columns:1fr}\\n}\\n@media(max-width:620px){\\n #kbv2-home{padding:20px 12px 38px}\\n #kbv2-home .panel{padding:18px}\\n #kbv2-home .head{align-items:flex-start;flex-direction:column}\\n #kbv2-home .discover{grid-template-columns:1fr}\\n #kbv2-home .trends{grid-template-columns:repeat(2,1fr)}\\n #kbv2-home .cat-body{padding:11px}\\n #kbv2-home .cat h3{font-size:14px}\\n #kbv2-home .cat p{display:none}\\n #kbv2-home .products{grid-auto-columns:76%}\\n #kbv2-home .arrow{display:none}\\n}\\n@media(prefers-reduced-motion:reduce){#kbv2-home *{scroll-behavior:auto!important;transition:none!important}}\\n</style>\\n\\n<div class=\\\"shell\\\">\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">A Little More Kawaii</div><h2>Discover Something To Love</h2><p class=\\\"sub\\\">Fresh drops, collectible worlds and surprise finds curated to make everyday feel a little sweeter.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">Explore collections →</a>\\n </div>\\n <div class=\\\"discover\\\">\\n  <article><div class=\\\"ico\\\">✦</div><h3>Fresh Drops</h3><p>The latest treasures and restocks arriving at Kawaii Blessings.</p></article>\\n  <article><div class=\\\"ico\\\">🎁</div><h3>Surprise & Collect</h3><p>Blind boxes, figures and collectible favorites made for the reveal.</p></article>\\n  <article><div class=\\\"ico\\\">♡</div><h3>Your Favorite Worlds</h3><p>Character-led collections, fandom favorites and everyday companions.</p></article>\\n  <article><div class=\\\"ico\\\">🎀</div><h3>Curated With Love</h3><p>Every collection presented with the soft Kawaii Blessings touch.</p></article>\\n </div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Trending Now</div><h2>What’s Kawaii Right Now?</h2><p class=\\\"sub\\\">A quick peek into character worlds and collections everyone is loving.</p></div>\\n  <a href=\\\"#kbv2-categories\\\" class=\\\"pill\\\">View all →</a>\\n </div>\\n <div id=\\\"kbv2-trends\\\" class=\\\"trends\\\"><div class=\\\"msg\\\">Loading collections…</div></div>\\n</section>\\n\\n<section class=\\\"promo\\\">\\n <div class=\\\"promo-in\\\">\\n  <div class=\\\"promo-copy\\\">\\n   <small>Blind Box Magic ✦</small>\\n   <h2>A Surprise In Every Box!</h2>\\n   <p>Discover mystery figures, collectible surprises and the joy of the unexpected.</p>\\n   <a id=\\\"kbv2-promo-link\\\" href=\\\"#kbv2-categories\\\" class=\\\"pill primary\\\">Shop Blind Boxes →</a>\\n  </div>\\n  <div id=\\\"kbv2-promo-media\\\" class=\\\"promo-media\\\"><div class=\\\"promo-fallback\\\">🎁</div></div>\\n </div>\\n</section>\\n\\n<section id=\\\"kbv2-categories\\\" class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Explore The Store</div><h2>Shop by Category ♡</h2><p class=\\\"sub\\\">Loaded directly from the enabled Bagisto categories and their existing thumbnail images.</p></div>\\n </div>\\n <div id=\\\"kbv2-category-grid\\\" class=\\\"categories\\\"><div class=\\\"msg\\\">Loading categories from Bagisto…</div></div>\\n</section>\\n\\n<section class=\\\"panel\\\">\\n <div class=\\\"head\\\">\\n  <div><div class=\\\"kicker\\\">Fresh Finds</div><h2>Just Landed ♡</h2><p class=\\\"sub\\\">Live product images, names and pricing fetched from Bagisto’s product API.</p></div>\\n  <a href=\\\"/search?sort=created_at-desc\\\" class=\\\"pill\\\">View new arrivals →</a>\\n </div>\\n <div class=\\\"products-wrap\\\">\\n  <button class=\\\"arrow left\\\" type=\\\"button\\\" aria-label=\\\"Previous\\\">‹</button>\\n  <div id=\\\"kbv2-products\\\" class=\\\"products\\\"><div class=\\\"msg\\\">Loading products…</div></div>\\n  <button class=\\\"arrow right\\\" type=\\\"button\\\" aria-label=\\\"Next\\\">›</button>\\n </div>\\n</section>\\n\\n<section class=\\\"values\\\">\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♕</div><h3>100% Authentic</h3><p>Official products and trusted merchandise, curated so customers can shop confidently.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">✦</div><h3>Made For Collectors</h3><p>Blind boxes, plushies and character collections worth keeping close.</p></article>\\n <article class=\\\"value\\\"><div class=\\\"ico\\\">♡</div><h3>Packed With Love</h3><p>Every order gets the care and joyful details the Kawaii Blessings name deserves.</p></article>\\n</section>\\n\\n</div>\\n<div id=\\\"kbv2-toast\\\" role=\\\"status\\\" aria-live=\\\"polite\\\"></div>\\n\\n<script>\\n(function(){\\n const root=document.getElementById(\\\"kbv2-home\\\");\\n if(!root||root.dataset.ready===\\\"1\\\")return; root.dataset.ready=\\\"1\\\";\\n\\n const ORDER=[\\n \\\"Kawaii Parisu Merch\\\",\\\"Sanrio collection\\\",\\\"Love and Deepspace Collection\\\",\\\"Blind Box\\\",\\n \\\"Plushies\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Pingu Collection\\\",\\n \\\"Sonny Angel collection\\\",\\\"Labubu\'s outfit\\\",\\\"Bag Charms\\\",\\\"Bags\\\",\\\"Kirby Collection\\\",\\n \\\"Sailor Moon Collection\\\",\\\"Shirts\\\"\\n ];\\n const TREND=[\\\"Sanrio collection\\\",\\\"Blind Box\\\",\\\"Popmart Collection\\\",\\\"Chiikawa\\\",\\\"Mofusand collection\\\",\\\"Sonny Angel collection\\\"];\\n const DESC={\\n \\\"Kawaii Parisu Merch\\\":\\\"Kawaii Parisu favorites and themed finds.\\\",\\n \\\"Sanrio collection\\\":\\\"Beloved character classics and charming everyday treasures.\\\",\\n \\\"Love and Deepspace Collection\\\":\\\"Fan-favorite merchandise from the Love and Deepspace world.\\\",\\n \\\"Blind Box\\\":\\\"Mystery collectibles and surprise figures waiting to be revealed.\\\",\\n \\\"Plushies\\\":\\\"Soft, huggable companions for every kawaii collection.\\\",\\n \\\"Popmart Collection\\\":\\\"Designer collectibles and popular Popmart releases.\\\",\\n \\\"Chiikawa\\\":\\\"Tiny characters, big charm and delightful adventures.\\\",\\n \\\"Mofusand collection\\\":\\\"Whimsical cats and irresistibly cute finds.\\\",\\n \\\"Pingu Collection\\\":\\\"Playful, nostalgic Pingu merchandise.\\\",\\n \\\"Sonny Angel collection\\\":\\\"Sweet mini figures and collectible favorites.\\\",\\n \\\"Labubu\'s outfit\\\":\\\"Adorable outfits and accessories — Labubu not included.\\\",\\n \\\"Bag Charms\\\":\\\"Little statement pieces for your favorite bags.\\\",\\n \\\"Bags\\\":\\\"Cute carryalls, pouches and everyday kawaii bags.\\\",\\n \\\"Kirby Collection\\\":\\\"Dreamy pink Kirby pieces with starry charm.\\\",\\n \\\"Sailor Moon Collection\\\":\\\"Magical girl treasures inspired by Sailor Moon.\\\",\\n \\\"Shirts\\\":\\\"Wearable kawaii styles for everyday looks.\\\"\\n };\\n const API={categories:\\\"/api/categories\\\",products:\\\"/api/products?sort=created_at-desc&limit=12\\\",cart:\\\"/api/checkout/cart\\\"};\\n const grid=root.querySelector(\\\"#kbv2-category-grid\\\"),trends=root.querySelector(\\\"#kbv2-trends\\\"),\\n products=root.querySelector(\\\"#kbv2-products\\\"),promo=root.querySelector(\\\"#kbv2-promo-media\\\"),\\n promoLink=root.querySelector(\\\"#kbv2-promo-link\\\"),toast=document.getElementById(\\\"kbv2-toast\\\");\\n\\n const esc=s=>String(s??\\\"\\\").replace(/&/g,\\\"&amp;\\\").replace(/</g,\\\"&lt;\\\").replace(/>/g,\\\"&gt;\\\").replace(/\\\"/g,\\\"&quot;\\\").replace(/\'/g,\\\"&#039;\\\");\\n const norm=s=>String(s||\\\"\\\").trim().toLowerCase();\\n const url=s=>{s=String(s||\\\"\\\").trim();if(!s)return\\\"#\\\";if(/^https?:\\\\/\\\\//i.test(s))return s;return s[0]===